    def _lease_from_row(self, row: Any) -> Lease:
        # PR2c: ``delegated_agent_id`` is the additive column added by
        # the lease-delegation migration. Older DBs (pre-migration) or
        # row mappings that do not surface the column still resolve to
        # None, keeping legacy call sites bit-for-bit compatible.
        keys = row.keys() if hasattr(row, "keys") else []
        delegated = row["delegated_agent_id"] if "delegated_agent_id" in keys else None
        return Lease(
            row["id"],
            row["task_id"],
            row["agent_id"],
            row["expires_at"],
            row["status"],
            row["created_at"],
            row["updated_at"],
            delegated,
        )

    def _machine_from_row(self, row: Any) -> Machine:
        keys = row.keys() if hasattr(row, "keys") else []
        hardware = json_loads(row["hardware"], {}) if "hardware" in keys else {}
        return Machine(
            row["id"],
            row["hostname"],
            json_loads(row["labels"], {}),
            json_loads(row["resources"], {}),
            bool(row["trusted"]),
            row["created_at"],
            row["updated_at"],
            row["last_seen_at"],
            hardware,
        )

    def _fleet_from_row(self, row: Any) -> Fleet:
        member_rows = self.store.query_all(
            "SELECT agent_id FROM fleet_agents WHERE fleet_id = ? ORDER BY agent_id",
            (row["id"],),
        )
        observed_rows = self.store.query_all(
            """
            SELECT agent_id
            FROM fleet_agent_observations
            WHERE fleet_id = ?
            ORDER BY agent_id
            """,
            (row["id"],),
        )
        agent_ids = [member["agent_id"] for member in member_rows]
        observed_agent_ids = [member["agent_id"] for member in observed_rows]
        return Fleet(
            row["id"],
            row["name"],
            row["description"],
            row["status"],
            json_loads(row["metadata"], {}),
            row["tenant_id"],
            agent_ids,
            row["created_at"],
            row["updated_at"],
            observed_agent_ids,
            sorted(set(observed_agent_ids) - set(agent_ids)),
        )

    def _agent_from_row(self, row: Any) -> Agent:
        keys = row.keys() if hasattr(row, "keys") else []
        running_digest = row["running_digest"] if "running_digest" in keys else None
        role_id = row["role_id"] if "role_id" in keys else None
        owner_human_id = row["owner_human_id"] if "owner_human_id" in keys else None
        visibility = str(row["visibility"] or "shared") if "visibility" in keys else "shared"
        hermes_instance_id = row["hermes_instance_id"] if "hermes_instance_id" in keys else None
        installed_packages = (
            json_loads(row["installed_packages"], {}) if "installed_packages" in keys else {}
        )
        dispatch_hold = bool(row["dispatch_hold"]) if "dispatch_hold" in keys else False
        dispatch_hold_reason = (
            row["dispatch_hold_reason"] if "dispatch_hold_reason" in keys else None
        )
        dispatch_hold_at = row["dispatch_hold_at"] if "dispatch_hold_at" in keys else None
        consecutive_lease_expiries_no_telemetry = (
            int(row["consecutive_lease_expiries_no_telemetry"])
            if "consecutive_lease_expiries_no_telemetry" in keys
            else 0
        )
        last_control_stream_published_at = (
            row["last_control_stream_published_at"]
            if "last_control_stream_published_at" in keys
            else None
        )
        last_control_stream_consumed_at = (
            row["last_control_stream_consumed_at"]
            if "last_control_stream_consumed_at" in keys
            else None
        )
        instance_kind = (
            row["instance_kind"] if "instance_kind" in keys else AgentInstanceKind.STATIC.value
        )
        return Agent(
            row["id"],
            row["machine_id"],
            row["name"],
            json_loads(row["capabilities"], []),
            json_loads(row["resources"], {}),
            row["status"],
            row["health_status"],
            row["current_task_id"],
            running_digest,
            row["created_at"],
            row["updated_at"],
            row["last_seen_at"],
            role_id,
            hermes_instance_id,
            installed_packages,
            dispatch_hold,
            dispatch_hold_reason,
            dispatch_hold_at,
            consecutive_lease_expiries_no_telemetry,
            last_control_stream_published_at,
            last_control_stream_consumed_at,
            row["deleted_at"] if "deleted_at" in keys else None,
            instance_kind,
            owner_human_id=owner_human_id,
            visibility=visibility,
        )

