    # Internal helpers

    def _record_history(
        self,
        task_id: str,
        event_type: str,
        actor: str,
        from_state: Optional[str],
        to_state: Optional[str],
        detail: Dict[str, Any],
        conn: Any = None,
    ) -> None:
        when = utcnow()
        writer = conn if conn is not None else self.store
        writer.execute(
            """
            INSERT INTO task_history (id, task_id, event_type, actor, from_state, to_state, detail, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                new_id("hist"),
                task_id,
                event_type,
                actor,
                from_state,
                to_state,
                json_dumps(detail),
                when,
            ),
        )
        self.observability.insert_observation(
            writer,
            "log",
            event_type,
            "control_plane",
            "task",
            "info",
            None,
            "",
            "task",
            task_id,
            {"actor": actor, "from_state": from_state, "to_state": to_state, **detail},
            when,
        )
        try:
            self.task_flow.record_event(
                task_id=task_id,
                event_type=event_type,
                from_state=from_state,
                to_state=to_state,
                detail=detail,
                when=when,
                writer=writer,
            )
        except Exception:  # noqa: BLE001 - analytics must not block task progress.
            logging.getLogger("mac.task_flow").warning(
                "task-flow materialization failed for %s / %s",
                task_id,
                event_type,
                exc_info=True,
            )
        self._record_history_notification(
            writer,
            task_id,
            event_type,
            actor,
            from_state,
            to_state,
            detail,
            when,
        )

    def _record_project_event(
        self,
        writer: Any,
        project_id: str,
        event_type: str,
        actor: str,
        detail: Dict[str, Any],
        when: str,
    ) -> None:
        payload = {"actor": actor, **ensure_json_object(detail)}
        writer.execute(
            """
            INSERT INTO project_events (id, project_id, event_type, actor, detail, created_at)
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (new_id("pevt"), project_id, event_type, actor, json_dumps(payload), when),
        )
        self.observability.insert_observation(
            writer,
            "log",
            event_type,
            "control_plane",
            "project",
            "info",
            None,
            "",
            "project",
            project_id,
            payload,
            when,
        )

    def _record_fleet_event(
        self,
        writer: Any,
        fleet_id: str,
        event_type: str,
        actor: str,
        detail: Dict[str, Any],
        when: str,
    ) -> None:
        payload = {"actor": actor, **ensure_json_object(detail)}
        writer.execute(
            """
            INSERT INTO fleet_events (id, fleet_id, event_type, actor, detail, created_at)
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (new_id("fevt"), fleet_id, event_type, actor, json_dumps(payload), when),
        )
        self.observability.insert_observation(
            writer,
            "log",
            event_type,
            "control_plane",
            "fleet",
            "info",
            None,
            "",
            "fleet",
            fleet_id,
            payload,
            when,
        )

    def _record_agent_lifecycle_event(
        self,
        writer: Any,
        agent_id: str,
        event_type: str,
        actor: str,
        detail: Dict[str, Any],
        when: str,
    ) -> None:
        payload = {"actor": actor, **ensure_json_object(detail)}
        writer.execute(
            """
            INSERT INTO agent_lifecycle_events (id, agent_id, event_type, actor, detail, created_at)
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (new_id("alce"), agent_id, event_type, actor, json_dumps(payload), when),
        )
        self.observability.insert_observation(
            writer,
            "log",
            event_type,
            "control_plane",
            "agent",
            "info",
            None,
            "",
            "agent",
            agent_id,
            payload,
            when,
        )

    def _record_history_notification(
        self,
        writer: Any,
        task_id: str,
        event_type: str,
        actor: str,
        from_state: Optional[str],
        to_state: Optional[str],
        detail: Dict[str, Any],
        when: str,
    ) -> None:
        payload = self._notification_payload_for_history(
            task_id,
            event_type,
            actor,
            from_state,
            to_state,
            detail,
            writer=writer,
        )
        if payload is None:
            return
        self.record_notification(
            payload["event_type"],
            payload["title"],
            payload["body"],
            subject_type="task",
            subject_id=task_id,
            channels=payload.get("channels"),
            metadata=payload.get("metadata"),
            conn=writer,
            created_at=when,
        )

    def _notification_payload_for_history(
        self,
        task_id: str,
        event_type: str,
        actor: str,
        from_state: Optional[str],
        to_state: Optional[str],
        detail: Dict[str, Any],
        *,
        writer: Any = None,
    ) -> Optional[JsonDict]:
        task_title = task_id
        try:
            # Reuse the caller's transaction connection when history and its
            # notification are emitted atomically.  Opening a second pooled
            # connection here can deadlock a small PostgreSQL pool: one claim
            # holds this transaction, a peer claim holds the other connection
            # while waiting on the same agent row, and both wait forever for a
            # third connection.  The direct lookup also sees the transaction's
            # own task writes.
            source = writer if writer is not None else self.store
            row = source.execute("SELECT title FROM tasks WHERE id = ?", (task_id,)).fetchone()
            if row is not None and row["title"]:
                task_title = str(row["title"])
        except Exception:
            pass
        metadata = {
            "actor": actor,
            "from_state": from_state,
            "to_state": to_state,
            **ensure_json_object(detail),
        }
        if event_type == "task.claimed":
            return {
                "event_type": event_type,
                "title": "Task claimed",
                "body": "%s claimed %s" % (actor, task_title),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.evidence_added":
            return {
                "event_type": event_type,
                "title": "Evidence recorded",
                "body": "%s added %s evidence for %s"
                % (actor, detail.get("kind", "task"), task_title),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.review_requested":
            return {
                "event_type": event_type,
                "title": "Review requested",
                "body": "Review requested for %s" % task_title,
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.review_claimed":
            return {
                "event_type": event_type,
                "title": "Review claimed",
                "body": "%s claimed review for %s" % (actor, task_title),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.review_completed":
            return {
                "event_type": event_type,
                "title": "Review completed",
                "body": "Review %s for %s" % (str(detail.get("status") or "completed"), task_title),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.published":
            return {
                "event_type": event_type,
                "title": "Task published",
                "body": "%s published %s" % (actor, task_title),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.lease_expired":
            return {
                "event_type": event_type,
                "title": "Task lease expired",
                "body": "%s was requeued after lease expiry" % task_title,
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.transitioned" and to_state == TaskState.NEEDS_INPUT.value:
            # Parking a task on a human question is the one transition an
            # operator must see: the work stops until a person answers. Emit it
            # as `task.question` -- the event type notifier channels subscribe
            # to -- and carry the answer instructions in the body so the alert
            # is actionable wherever it lands. The `hermes` hint lets both an
            # explicit subscription and the auto-discovery fallback deliver it.
            lines: List[str] = []
            questions = detail.get("questions") or []
            for index, item in enumerate(questions, start=1):
                question = ensure_json_object(item)
                text = str(question.get("question") or "").strip()
                if not text:
                    continue
                prefix = "%d. " % index if len(questions) > 1 else ""
                lines.append("%s%s" % (prefix, text))
                why = str(question.get("why") or "").strip()
                if why:
                    lines.append("   why: %s" % why)
                options = [
                    str(opt).strip() for opt in (question.get("options") or []) if str(opt).strip()
                ]
                if options:
                    lines.append("   options: %s" % ", ".join(options))
            why = str(detail.get("why") or "").strip()
            if why:
                lines.append("why: %s" % why)
            lines.append('Answer with: mac task answer %s --answer "..."' % task_id)
            return {
                "event_type": "task.question",
                "title": "Answer needed: %s" % task_title,
                "body": "\n".join(lines),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        if event_type == "task.transitioned" and to_state in {
            TaskState.RUNNING.value,
            TaskState.WAITING.value,
            TaskState.BLOCKED.value,
            TaskState.NEEDS_REVIEW.value,
            TaskState.REVIEWING.value,
            TaskState.COMPLETED.value,
            TaskState.FAILED.value,
            TaskState.CANCELLED.value,
        }:
            return {
                "event_type": "task.%s" % to_state,
                "title": "Task %s" % to_state.replace("_", " "),
                "body": "%s moved to %s" % (task_title, to_state),
                "channels": ["dashboard", "hermes"],
                "metadata": metadata,
            }
        return None

    @staticmethod
    def _dependency_join_policy(task: Task) -> str:
        metadata = ensure_json_object(task.metadata)
        dependency_policy = ensure_json_object(metadata.get("dependency_policy"))
        coordination = ensure_json_object(metadata.get("coordination"))
        default_join = (
            "all_settled"
            if coordination.get("mode") == "cooperative_integration"
            else "all_success"
        )
        join = (
            str(dependency_policy.get("join") or coordination.get("join_policy") or default_join)
            .strip()
            .lower()
        )
        if join not in {"all_success", "all_settled"}:
            raise ValidationError(
                "unsupported dependency join policy %r for task %s" % (join, task.id)
            )
        return join

    @staticmethod
    def _dependency_state_satisfies_join(state: str, metadata: Any, join: str) -> bool:
        if state == TaskState.COMPLETED.value:
            return True
        if state == TaskState.CANCELLED.value:
            # A cancellation whose disposition asserts the underlying goal was
            # met elsewhere (the same AUTO_CLEANUP_DISPOSITIONS set governing
            # repository-ref cleanup: duplicate/superseded/not_applicable)
            # satisfies even the strict "all_success" join -- it is not a
            # failure to route around, it IS the resolution. Confirmed live:
            # an onboarding task was closed --cancelled --disposition
            # not_applicable after its repository contract was registered
            # through a different, equally valid path; its 10 dependents had
            # no join-policy opt-in (the default is "all_success") and stayed
            # permanently blocked/waiting until dependencies were cleared by
            # hand. A genuine "this isn't happening" cancellation
            # (disposition=preserve, or none) still only satisfies
            # "all_settled" below, unchanged.
            lifecycle = ensure_json_object(
                ensure_json_object(metadata).get("repository_ref_lifecycle")
            )
            disposition = str(lifecycle.get("disposition") or "").strip().lower()
            if disposition in AUTO_CLEANUP_DISPOSITIONS:
                return True
        if join != "all_settled":
            return False
        if state in {
            TaskState.FAILED.value,
            TaskState.CANCELLED.value,
        }:
            # Both are terminal: no retry proceeds from either. The spec's
            # "executor failures that may still retry ... continue to hold the
            # integration parent" is about a BLOCKED child awaiting retry,
            # which is handled below by requiring the supervised record.
            return True
        dependency_resolution = ensure_json_object(
            ensure_json_object(metadata).get("dependency_resolution")
        )
        return (
            state == TaskState.BLOCKED.value
            and dependency_resolution.get("status") == "unsatisfied"
        )

    @classmethod
    def _dependency_satisfies_join(cls, dependency: Task, join: str) -> bool:
        return cls._dependency_state_satisfies_join(dependency.state, dependency.metadata, join)

    def _dependencies_satisfied(
        self,
        task: Task,
        *,
        dependency_ids: Optional[Sequence[str]] = None,
    ) -> bool:
        join = self._dependency_join_policy(task)
        canonical_ids = (
            list(dependency_ids)
            if dependency_ids is not None
            else self._canonical_task_dependency_ids(task.id)
        )
        for dep_id in canonical_ids:
            dep = self.get_task(dep_id)
            if not self._dependency_satisfies_join(dep, join):
                return False
        return True

    def _dependency_settlement(
        self,
        task: Task,
        *,
        dependency_ids: Optional[Sequence[str]] = None,
    ) -> JsonDict:
        """WHY this task's join settled, per dependency.

        ``_dependencies_satisfied`` answers a yes/no, and under ``all_settled``
        that single bit collapses two materially different facts:

          * the dependency RAN and produced output -- the parent can proceed;
          * the dependency was CANCELLED and produced nothing -- it cannot.

        Observed end to end 2026-08-05 in about five minutes: four children
        were cancelled at 17:17:14, task_c5407d23 went waiting -> running at
        17:17:45 having waited since 2026-07-31, and failed 3/3 by 17:22:53.
        Its own diagnosis named the cause -- "missing child outputs". It
        adjudicates candidates those children were supposed to enumerate, and
        they will now never exist.

        ``all_settled`` is right and stays: a cancelled dependency must not
        block a parent forever. What was missing is that nothing recorded which
        kind of settling happened, so neither the executing agent nor the
        operator could tell a parent with inputs from one without.

        This reports; it does not gate. Declining to dispatch when everything
        settled by cancellation is option 3 in the filing and is deliberately
        NOT taken here -- it would reintroduce the permanent stall
        ``all_settled`` exists to prevent, and wants its own decision.
        """
        join = self._dependency_join_policy(task)
        canonical_ids = (
            list(dependency_ids)
            if dependency_ids is not None
            else self._canonical_task_dependency_ids(task.id)
        )
        per_dependency: JsonDict = {}
        settled_without_output: List[str] = []
        for dep_id in canonical_ids:
            try:
                dep = self.get_task(dep_id)
            except NotFoundError:
                # A dependency that no longer exists produced nothing either.
                per_dependency[dep_id] = {"state": "missing", "produced_output": False}
                settled_without_output.append(dep_id)
                continue
            produced = dep.state == TaskState.COMPLETED.value
            per_dependency[dep_id] = {
                "state": dep.state,
                "produced_output": produced,
                "satisfied": self._dependency_satisfies_join(dep, join),
            }
            if not produced:
                settled_without_output.append(dep_id)
        return {
            "schema": "mac.dependency_settlement.v1",
            "join": join,
            "dependencies": per_dependency,
            #: Dependencies that settled the join without producing anything.
            #: Non-empty means the parent is about to run against inputs that
            #: do not exist.
            "settled_without_output": settled_without_output,
            "all_inputs_present": not settled_without_output,
            "observed_at": utcnow(),
        }

    def _record_dependency_settlement(
        self,
        task: Task,
        settlement: JsonDict,
    ) -> Task:
        """Stamp the settlement onto the task the executor will read.

        The transition detail alone is not enough: an executor reads task.json,
        not the transition history, so a parent released over cancelled
        children needs to be able to see that from its own metadata.
        """
        if settlement.get("all_inputs_present"):
            return task
        metadata = ensure_json_object(getattr(task, "metadata", None))
        resolution = ensure_json_object(metadata.get("dependency_resolution"))
        resolution["settlement"] = settlement
        metadata["dependency_resolution"] = resolution
        try:
            return self.update_task(task.id, metadata=metadata, actor="dependency-reconciliation")
        except Exception:  # noqa: BLE001 - provenance must not block dispatch
            return task

    def _canonical_task_dependency_ids(
        self,
        task_id: str,
        *,
        conn: Optional[Any] = None,
    ) -> List[str]:
        """Read dependency authority from normalized edges, in stable order."""

        sql = (
            "SELECT dependency_task_id FROM task_edges WHERE task_id = ? "
            "ORDER BY edge_position, dependency_task_id"
        )
        rows = (
            conn.execute(sql, (task_id,)).fetchall()
            if conn is not None
            else self.store.query_all(sql, (task_id,))
        )
        return [str(row["dependency_task_id"]) for row in rows]

    def _dependency_supervision_is_recoverable(self, task: Task) -> bool:
        """Whether this task is BLOCKED only because a dependency was terminal.

        Distinguishes the two reasons ``_blocked_task_requires_manual_repair``
        answers True for. A supervised dependency block is recoverable: if the
        dependency is later replaced or completed, the task should run. An
        actionable block (an executor failure, an explicit
        ``manual_repair_required``) is not, and must keep waiting for a human.
        """

        if task.state != TaskState.BLOCKED.value:
            return False
        dependency_resolution = ensure_json_object(
            ensure_json_object(getattr(task, "metadata", None)).get("dependency_resolution")
        )
        return dependency_resolution.get("status") == "unsatisfied"

    def _clear_dependency_supervision(self, task: Task) -> Task:
        """Drop the supervised marker once the dependencies are satisfied."""

        metadata = ensure_json_object(getattr(task, "metadata", None))
        resolution = ensure_json_object(metadata.get("dependency_resolution"))
        resolution.update(
            {
                "status": "resolved",
                "unsatisfied": {},
                "updated_at": utcnow(),
            }
        )
        metadata["dependency_resolution"] = resolution
        return self.update_task(
            task.id,
            metadata=metadata,
            actor="dependency-reconciliation",
        )

    def _blocked_task_requires_manual_repair(self, task: Task) -> bool:
        if task.state != TaskState.BLOCKED.value:
            return False
        dependency_resolution = ensure_json_object(
            ensure_json_object(getattr(task, "metadata", None)).get("dependency_resolution")
        )
        if dependency_resolution.get("status") == "unsatisfied":
            # This is a supervised, durable branch outcome consumed by an
            # all-settled integration parent.  It is not the historic
            # dependency-wait encoding below and must not be migrated back to
            # WAITING by a dispatcher sweep.
            return True
        for event in reversed(self.task_history(task.id, limit=20)):
            if event.to_state != TaskState.BLOCKED.value:
                continue
            detail = ensure_json_object(event.detail)
            reason = str(detail.get("reason") or "").strip()
            # In the current state model every non-legacy BLOCKED reason is an
            # actionable execution/operator condition. Only the two historic
            # dependency-wait encodings may be auto-migrated/opened here.
            return detail.get("manual_repair_required") is True or reason not in {
                "",
                "waiting_on_dependencies",
                "dependencies_incomplete",
            }
        return False

    def _merge_attempt_failure_salvage_metadata(
        self,
        existing: Any,
        derived: Mapping[str, Any],
    ) -> JsonDict:
        merged = dict(existing) if isinstance(existing, Mapping) else {}
        for key, value in derived.items():
            if value in (None, "", [], {}):
                continue
            if key in {"recorded_lessons", "published_children"}:
                current = _metadata_string_list(merged.get(key))
                for item in _metadata_string_list(value):
                    if item not in current:
                        current.append(item)
                if current:
                    merged[key] = current
                continue
            merged.setdefault(key, value)
        return merged

    def _record_attempt_failure_classification(self, task: Task) -> Tuple[str, JsonDict]:
        history = [event.to_dict() for event in self.task_history(task.id, limit=100)]
        classification = classify_attempt_failure(history)
        metadata = ensure_json_object(task.metadata)
        metadata["failure_class"] = classification.failure_class
        if classification.salvage:
            metadata["salvage"] = self._merge_attempt_failure_salvage_metadata(
                metadata.get("salvage"),
                classification.salvage,
            )
        self.store.execute(
            "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
            (json_dumps(metadata), utcnow(), task.id),
        )
        return classification.failure_class, dict(classification.salvage)

    def _evidence_output_tail(
        self, task_id: str, *, evidence_id: Optional[str] = None
    ) -> Tuple[str, str]:
        """Recover a failure's output from the durable stdout/stderr artifacts.

        The worker uploads stdout.txt and stderr.txt as evidence artifacts on
        every attempt, but the failure-diagnosis path only ever read the
        transition ``detail`` dict. Any transition that omitted an output field
        was therefore recorded as "transition supplied no stdout, stderr,
        output, log, or tail field" while the bytes sat on the hub -- true of
        1,464 of 1,488 failure records observed on 2026-07-31. Join to them.
        """

        clauses = ["a.task_id = ?", "a.artifact_type IN (?, ?)"]
        params: List[Any] = [task_id, "stderr", "stdout"]
        if evidence_id:
            clauses.append("a.evidence_id = ?")
            params.append(evidence_id)
        try:
            rows = self.store.query_all(
                "SELECT a.artifact_type, a.content_base64 FROM evidence_artifacts a "
                "WHERE " + " AND ".join(clauses) + " ORDER BY a.created_at DESC, a.id DESC "
                "LIMIT 8",
                tuple(params),
            )
        except Exception:  # noqa: BLE001 - diagnosis must never break a transition
            return "", "evidence artifact lookup failed"
        chunks: List[str] = []
        for row in rows or []:
            try:
                raw = row["content_base64"]
            except (KeyError, IndexError, TypeError):
                continue
            if not raw:
                continue
            try:
                decoded = base64.b64decode(str(raw), validate=False).decode(
                    "utf-8", errors="replace"
                )
            except Exception:  # noqa: BLE001 - one bad artifact must not hide the rest
                continue
            if decoded.strip():
                chunks.append(decoded)
        if not chunks:
            return "", "no stdout/stderr evidence artifact exists for this task"
        # Reuse the redaction and bounding the detail path already applies.
        tail, unavailable = _diagnostic_output_tail({"output_tail": "\n".join(chunks)})
        if not tail:
            return "", unavailable or "evidence artifact contained no usable output"
        return tail, ""

    def _attempt_failure_output(self, task: Task) -> Tuple[str, str]:
        """Return the newest durable output tail from the exhausted attempts."""
        for event in reversed(self.task_history(task.id, limit=100)):
            detail = ensure_json_object(event.detail)
            output_tail, unavailable = _diagnostic_output_tail(detail)
            if output_tail:
                return output_tail, ""
            diagnosis = ensure_json_object(detail.get("diagnosis"))
            output_tail, unavailable = _diagnostic_output_tail(diagnosis)
            if output_tail:
                return output_tail, ""
        # Nothing in history carried output. The bytes are still on the hub as
        # durable evidence artifacts, so ask for them before declaring the
        # failure undiagnosable.
        artifact_tail, artifact_reason = self._evidence_output_tail(task.id)
        if artifact_tail:
            return artifact_tail, ""
        history_reason = (
            "no captured stdout, stderr, output, log, or tail exists in attempt history"
        )
        return "", (
            "%s; %s" % (history_reason, artifact_reason) if artifact_reason else history_reason
        )

    def _has_actionable_environment_repair_evidence(
        self,
        task: Task,
        *,
        output_tail: str,
        salvage: Mapping[str, Any],
    ) -> bool:
        """Require a concrete repair target before manufacturing a dependency.

        A run of lease expiries with no telemetry identifies a worker/capacity
        incident, not a task-specific prerequisite.  Turning that signal into
        a generic "repair environment" task wedges the parent behind work that
        cannot say what to repair.  Durable output, preserved work, or an
        explicit failure/remediation diagnosis is actionable; bare
        claim/expiry bookkeeping is not.
        """
        if output_tail or salvage:
            return True
        for event in reversed(self.task_history(task.id, limit=100)):
            detail = ensure_json_object(event.detail)
            diagnosis = ensure_json_object(detail.get("diagnosis"))
            for candidate in (diagnosis, detail):
                if any(
                    str(candidate.get(key) or "").strip()
                    for key in (
                        "reason",
                        "failure",
                        "error",
                        "problem",
                        "problems",
                        "remediation",
                    )
                ):
                    return True
        return False

    def _exhausted_attempt_terminal_transition(
        self,
        task: Task,
        detail: Mapping[str, Any],
    ) -> Tuple[str, JsonDict]:
        failure_class, salvage = self._record_attempt_failure_classification(task)
        transition_detail = dict(detail)
        defer_attempt_reset = bool(transition_detail.pop("_defer_attempt_reset", False))
        suppress_environment_repair = bool(
            transition_detail.pop("_suppress_environment_repair", False)
        )
        transition_detail["failure_class"] = failure_class
        output_tail, unavailable = self._attempt_failure_output(task)
        if output_tail:
            transition_detail.setdefault("output_tail", output_tail)
        else:
            transition_detail.setdefault("output_tail_unavailable_reason", unavailable)
        if salvage:
            transition_detail["salvage"] = salvage
        recent_history = self.task_history(task.id, limit=100)
        contract_failure = any(
            "verification_contract_failed" in json_dumps(ensure_json_object(event.detail)).lower()
            for event in recent_history
        )
        repair_policy = ensure_json_object(ensure_json_object(task.metadata).get("repair_policy"))
        # Contract failures normally belong to the original task and should
        # fail visibly after its bounded retries.  A repository may explicitly
        # opt into a separate prerequisite only when it has a real independent
        # repair workflow.
        contract_repair = bool(
            contract_failure and repair_policy.get("contract_prerequisite") is True
        )
        environment_repair = bool(
            failure_class == "environment"
            and not suppress_environment_repair
            and repair_policy.get("environment_prerequisite") is True
            and self._has_actionable_environment_repair_evidence(
                task,
                output_tail=output_tail,
                salvage=salvage,
            )
        )
        repairable_prerequisite = contract_repair or environment_repair
        # Recursion base case (2026-07-14 churn root cause): a repair task that
        # itself exhausts its attempts must NOT spawn a repair-of-repair. Without
        # this guard every deterministic infra failure (e.g. a stale attestation
        # key) grew an unbounded chain — "Repair prerequisites: Repair
        # prerequisites: ..." — with each level burning a full attempt budget on
        # the identical failure (observed: 175 of 267 new tasks in 12h were
        # repair tasks; 5 completions). A failed repair task dead-letters so its
        # parent's failure surfaces for real diagnosis instead of multiplying.
        origin = ensure_json_object(ensure_json_object(task.metadata).get("origin"))
        if str(origin.get("type") or "").endswith("_prerequisite"):
            transition_detail["reason"] = "repair_task_exhausted_no_recursion"
            transition_detail["manual_repair_required"] = True
            return TaskState.FAILED.value, transition_detail
        if repairable_prerequisite:
            # Classification is persisted immediately above. Reload before
            # adding dependency metadata so update_task cannot overwrite the
            # freshly recorded failure class and salvage with the stale task
            # object passed into this method.
            metadata = ensure_json_object(self.get_task(task.id).metadata)
            repair_metadata_key = (
                "contract_repair_task_id" if contract_repair else "environment_repair_task_id"
            )
            origin_type = "contract_prerequisite" if contract_repair else "environment_prerequisite"
            repair_id = str(metadata.get(repair_metadata_key) or "").strip()
            if not repair_id:
                if contract_repair:
                    repair_title = "Repair contract prerequisites: %s" % task.title
                    repair_description = (
                        "Repair the repository contract for parent task %s: commit all "
                        "changes, pass the required verification gate, and push a remote "
                        "ref/PR. The parent task will retry automatically after completion."
                    ) % task.id
                else:
                    repair_title = "Repair environment prerequisites: %s" % task.title
                    repair_description = (
                        "Repair the execution environment prerequisite for parent task %s. "
                        "Use the parent failure evidence and salvage metadata to restore the "
                        "required agent, service, credential source, or toolchain. The parent "
                        "task will retry automatically after this prerequisite completes."
                    ) % task.id
                # The repair identity is an idempotency key, not a random
                # allocation. If a sweeper crashes after creating the repair
                # but before detaching the expired lease, a recovery sweep (or
                # an exceptionally stale finalizer takeover) reuses this exact
                # task instead of manufacturing duplicate prerequisites.
                repair_id = (
                    "task_repair_%s"
                    % hashlib.sha256(
                        (task.id + ":" + repair_metadata_key).encode("utf-8")
                    ).hexdigest()[:24]
                )
                failure_fingerprint = hashlib.sha256(
                    json_dumps(
                        {
                            "failure_class": failure_class,
                            "output_tail": output_tail[-2000:],
                            "origin_type": origin_type,
                        }
                    ).encode("utf-8")
                ).hexdigest()
                repair = self.create_task(
                    repair_title,
                    description=repair_description,
                    project=task.project,
                    priority=task.priority,
                    required_capabilities=task.required_capabilities,
                    metadata={
                        "dispatch_class": "recovery",
                        "due_at": utcnow(),
                        "failure_fingerprint": "sha256:%s" % failure_fingerprint,
                        "origin": {
                            "type": origin_type,
                            "parent_task_id": task.id,
                        },
                    },
                    actor="dispatcher.tick",
                    _task_id=repair_id,
                )
                repair_id = repair.id
                repair_origin = ensure_json_object(
                    ensure_json_object(repair.metadata).get("origin")
                )
                if (
                    repair_origin.get("type") != origin_type
                    or repair_origin.get("parent_task_id") != task.id
                ):
                    raise ValidationError("deterministic repair id collides with unrelated task")
                metadata[repair_metadata_key] = repair_id
                if contract_repair:
                    metadata["contract_repair_status"] = "waiting"
                canonical_dependencies = self._canonical_task_dependency_ids(task.id)
                # _update_task_fields, not update_task: this is the hub
                # attaching a repair task to work it is already failing, not an
                # operator editing scope. Routing it through update_task would
                # trigger the ADR 0020 stop/restart cycle against a RUNNING
                # task mid-expiry, revoking the very lease this path is
                # reconciling.
                self._update_task_fields(
                    task.id,
                    dependencies=[*canonical_dependencies, repair_id],
                    metadata=metadata,
                    actor="dispatcher.tick",
                    _preserve_control_plane_publication_metadata=True,
                )
                transition_detail["repair_task_id"] = repair_id
            repair_task = self.get_task(repair_id)
            repair_origin = ensure_json_object(
                ensure_json_object(repair_task.metadata).get("origin")
            )
            if (
                repair_origin.get("type") != origin_type
                or repair_origin.get("parent_task_id") != task.id
            ):
                raise ValidationError("repair prerequisite does not match its parent and origin")
            if not defer_attempt_reset:
                self.store.execute(
                    "UPDATE tasks SET attempt_count = 0, updated_at = ? WHERE id = ?",
                    (utcnow(), task.id),
                )
            else:
                transition_detail["reset_attempt_count"] = True
            transition_detail["reason"] = (
                "waiting_on_contract_prerequisite"
                if contract_repair
                else "waiting_on_environment_prerequisite"
            )
            transition_detail["manual_repair_required"] = False
            return TaskState.WAITING.value, transition_detail
        if failure_class == "superseded":
            transition_detail["reason"] = "superseded"
            return TaskState.CANCELLED.value, transition_detail
        if contract_failure and not contract_repair:
            transition_detail["reason"] = "verification_contract_failed"
            transition_detail["manual_repair_required"] = True
        elif failure_class == "environment" and not environment_repair:
            if transition_detail.get("reason") in (None, "", "max attempts"):
                transition_detail["reason"] = "environment_failure_without_actionable_evidence"
            transition_detail["manual_repair_required"] = True
        return TaskState.FAILED.value, transition_detail

    def _blocked_attempt_retry_backoff_seconds(self, task: Task) -> int:
        per_attempt = _int_env(
            "MAC_BLOCKED_ATTEMPT_RETRY_BACKOFF_SECONDS",
            DEFAULT_BLOCKED_ATTEMPT_RETRY_BACKOFF_SECONDS,
        )
        return per_attempt * max(1, int(task.attempt_count or 0))

    def _blocked_attempt_retry_ready_at(
        self,
        task: Task,
        *,
        backoff_seconds: Optional[int] = None,
    ) -> str:
        backoff = (
            int(backoff_seconds)
            if backoff_seconds is not None
            else self._blocked_attempt_retry_backoff_seconds(task)
        )
        return (parse_time(task.updated_at) + timedelta(seconds=backoff)).isoformat(
            timespec="microseconds"
        )

    def _blocked_attempt_non_retryable_marker(self, task: Task) -> Optional[str]:
        if task.state != TaskState.BLOCKED.value:
            return None
        for event in reversed(self.task_history(task.id, limit=20)):
            if event.to_state != TaskState.BLOCKED.value:
                continue
            marker = _non_retryable_blocked_attempt_marker(event.detail)
            if marker:
                return marker
            break
        metadata = ensure_json_object(task.metadata)
        activity = metadata.get("activity")
        if isinstance(activity, list):
            for entry in reversed(activity):
                entry_dict = ensure_json_object(entry) if isinstance(entry, dict) else {}
                phase = str(entry_dict.get("phase") or "").strip().lower()
                if phase != "diagnosis":
                    continue
                return _non_retryable_blocked_attempt_marker(entry_dict)
        for key in ("diagnosis", "failure_diagnosis", "diagnosis_code"):
            marker = _non_retryable_blocked_attempt_marker(metadata.get(key))
            if marker:
                return marker
        return None

    def _latest_blocked_attempt_event(self, task: Task) -> Optional[HistoryEvent]:
        if task.state != TaskState.BLOCKED.value:
            return None
        for event in reversed(self.task_history(task.id, limit=100)):
            if event.to_state == TaskState.BLOCKED.value:
                return event
        return None

    def _blocked_attempt_failure_count(
        self,
        task: Task,
        fingerprint: str,
        *,
        retry_generation: int,
    ) -> int:
        return sum(
            1
            for event in self.task_history(task.id, limit=100)
            if event.to_state == TaskState.BLOCKED.value
            and _nonnegative_int(
                ensure_json_object(event.detail).get("retry_generation"),
                default=0,
            )
            == retry_generation
            and _blocked_attempt_failure_fingerprint(event.detail) == fingerprint
        )

    def _requeue_after_node_fault(
        self,
        task: Task,
        *,
        agent_id: str,
        fault: str,
        fingerprint: str,
        detail: Mapping[str, Any],
        now: str,
    ) -> Task:
        """Hold the faulty node and reopen the task without charging the attempt."""

        hold_reason = NODE_FAULT_QUARANTINE_PREFIX + fault
        try:
            agent: Optional[Agent] = self.get_agent(agent_id)
        except NotFoundError:
            agent = None
        quarantined = False
        if agent is not None and not agent.dispatch_hold:
            self.set_agent_dispatch_hold(agent_id, hold_reason)
            quarantined = True
            self.record_log(
                "agent.auto_quarantined",
                level="warning",
                layer="control_plane",
                source="dispatcher",
                subject_type="agent",
                subject_id=agent_id,
                detail={"agent_id": agent_id, "task_id": task.id, "reason": hold_reason},
            )
        self._record_retry_worker_exclusion(
            task,
            agent_id=agent_id,
            fingerprint=fingerprint,
            retry_kind="node_fault",
            now=now,
        )
        self.store.execute(
            "UPDATE tasks SET attempt_count = CASE WHEN attempt_count > 0 "
            "THEN attempt_count - 1 ELSE 0 END WHERE id = ?",
            (task.id,),
        )
        reopen_detail = {
            **detail,
            "reason": "node fault on %s (%s): requeued without charging an attempt"
            % (agent_id, fault),
            "node_fault": fault,
            "node_fault_agent_id": agent_id,
            "node_quarantined": quarantined,
            "attempt_refunded": True,
        }
        reopened = self._transition_task_internal(
            task.id,
            TaskState.OPEN.value,
            "dispatcher.tick",
            reopen_detail,
        )
        self._record_history(
            task.id,
            "task.auto_reopened",
            "dispatcher.tick",
            TaskState.BLOCKED.value,
            TaskState.OPEN.value,
            reopen_detail,
        )
        return reopened

    def _attempt_hit_router_outage(self, task: Task) -> bool:
        """Whether the hub router answered "no provider could serve" to this
        task during its latest attempt, and the task has outage requeues left.

        The router records every request as ``llm.route``, attributed to the
        task, including the in-sandbox route probe that runs before any work.
        On 2026-10-03 and 10-05 provider outages of 4-7 minutes cost two tasks
        their attempt: one coding agent exited on the router's 503, and one
        attempt never started because the route probe timed out."""
        metadata = ensure_json_object(task.metadata)
        limit = _int_env(
            "MAC_ROUTER_OUTAGE_REQUEUES", DEFAULT_ROUTER_OUTAGE_REQUEUES, minimum=0
        )
        if _nonnegative_int(metadata.get("router_outage_requeues")) >= limit:
            return False
        row = self.store.query_one(
            "SELECT created_at FROM task_history WHERE task_id = ? AND event_type = ? "
            "ORDER BY created_at DESC LIMIT 1",
            (task.id, "task.claimed"),
        )
        if row is None:
            return False
        events = self.list_observability(
            kind="log",
            name="llm.route",
            subject_type="task",
            subject_id=task.id,
            since=str(row["created_at"]),
            limit=1000,
        )
        return any(
            ensure_json_object(event.detail).get("outcome") == "all_providers_unavailable"
            for event in events
        )

    def _requeue_after_router_outage(self, task: Task, *, detail: JsonDict) -> Task:
        """Reopen a task whose attempt a router outage cost, without charging it."""
        metadata = ensure_json_object(task.metadata)
        count = _nonnegative_int(metadata.get("router_outage_requeues")) + 1
        metadata["router_outage_requeues"] = count
        self.store.execute(
            "UPDATE tasks SET metadata = ?, attempt_count = CASE WHEN attempt_count > 0 "
            "THEN attempt_count - 1 ELSE 0 END WHERE id = ?",
            (json_dumps(metadata), task.id),
        )
        reopen_detail = {
            **detail,
            "reason": "model router outage during the attempt: requeued without charging an attempt",
            "router_outage": True,
            "router_outage_requeues": count,
            "attempt_refunded": True,
        }
        reopened = self._transition_task_internal(
            task.id,
            TaskState.OPEN.value,
            "dispatcher.tick",
            reopen_detail,
        )
        self._record_history(
            task.id,
            "task.auto_reopened",
            "dispatcher.tick",
            TaskState.BLOCKED.value,
            TaskState.OPEN.value,
            reopen_detail,
        )
        return reopened

    def _record_retry_worker_exclusion(
        self,
        task: Task,
        *,
        agent_id: str,
        fingerprint: str,
        retry_kind: str,
        now: str,
    ) -> None:
        metadata = ensure_json_object(task.metadata)
        excluded = _metadata_string_list(metadata.get("retry_excluded_agent_ids"))
        if agent_id.startswith("agent_") and agent_id not in excluded:
            excluded.append(agent_id)
        if excluded:
            metadata["retry_excluded_agent_ids"] = excluded
        metadata["retry_failure_fingerprint"] = fingerprint
        metadata["retry_failure_kind"] = retry_kind
        self.store.execute(
            "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
            (json_dumps(metadata), now, task.id),
        )

    def _ensure_shared_failure_incident(
        self,
        task: Task,
        *,
        fingerprint: str,
        detail: Mapping[str, Any],
    ) -> Task:
        """Create one fleet incident for a repeated shared-infrastructure failure."""
        incident_id = "task_incident_%s" % fingerprint.removeprefix("sha256:")[:24]
        try:
            incident = self.get_task(incident_id)
        except NotFoundError:
            summary = str(
                detail.get("reason")
                or detail.get("failure")
                or detail.get("error")
                or "shared control-plane transport failure"
            ).strip()
            incident = self.create_task(
                "Investigate shared fleet failure %s" % incident_id[-8:],
                description=(
                    "Investigate and repair the shared fleet/control-plane failure "
                    "identified by fingerprint %s. Affected task %s reported: %s. "
                    "This incident is deliberately shared across affected tasks; do "
                    "not create per-task repair children."
                )
                % (fingerprint, task.id, summary[:1000]),
                project="mac",
                priority=min(int(task.priority), 1),
                required_capabilities=["ops"],
                metadata={
                    "dispatch_class": "recovery",
                    "due_at": utcnow(),
                    "failure_fingerprint": fingerprint,
                    "affected_task_ids": [task.id],
                    "origin": {
                        "type": "shared_environment_incident",
                        "representative_task_id": task.id,
                    },
                },
                actor="dispatcher.tick",
                _task_id=incident_id,
            )
        incident_fingerprint = str(
            ensure_json_object(incident.metadata).get("failure_fingerprint") or ""
        )
        if incident_fingerprint != fingerprint:
            raise ValidationError("deterministic shared incident id collides with unrelated task")
        incident_metadata = ensure_json_object(incident.metadata)
        affected = _metadata_string_list(incident_metadata.get("affected_task_ids"))
        if task.id not in affected:
            affected.append(task.id)
            incident_metadata["affected_task_ids"] = affected
            self.store.execute(
                "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
                (json_dumps(incident_metadata), utcnow(), incident.id),
            )
            incident = self.get_task(incident.id)
        metadata = ensure_json_object(task.metadata)
        metadata["shared_failure_incident_task_id"] = incident.id
        metadata["retry_failure_fingerprint"] = fingerprint
        self.store.execute(
            "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
            (json_dumps(metadata), utcnow(), task.id),
        )
        return incident

    def _auto_retry_blocked_attempt_task(
        self,
        task: Task,
        *,
        now: str,
    ) -> Tuple[Optional[Task], Optional[Task]]:
        if task.state != TaskState.BLOCKED.value:
            return None, None
        if int(task.attempt_count or 0) <= 0:
            return None, None
        dependency_ids = self._canonical_task_dependency_ids(task.id)
        if dependency_ids and not self._dependencies_satisfied(
            task,
            dependency_ids=dependency_ids,
        ):
            return None, None
        latest_event = self._latest_blocked_attempt_event(task)
        latest_detail = ensure_json_object(latest_event.detail) if latest_event is not None else {}
        retry_generation = _nonnegative_int(
            ensure_json_object(task.metadata).get("retry_generation"),
            default=0,
        )
        retry_kind = _blocked_attempt_retry_kind(latest_detail)
        fingerprint = _blocked_attempt_failure_fingerprint(latest_detail)
        same_failure_count = self._blocked_attempt_failure_count(
            task,
            fingerprint,
            retry_generation=retry_generation,
        )
        prior_agent_id = str(latest_event.actor if latest_event is not None else "")
        backoff_seconds = self._blocked_attempt_retry_backoff_seconds(task)
        ready_at = self._blocked_attempt_retry_ready_at(
            task,
            backoff_seconds=backoff_seconds,
        )
        base_detail: JsonDict = {
            "via": "auto_retry",
            "attempt_count": task.attempt_count,
            "max_attempts": task.max_attempts,
            "backoff_seconds": backoff_seconds,
            "blocked_since": task.updated_at,
            "ready_at": ready_at,
            "retry_kind": retry_kind,
            "retry_generation": retry_generation,
            "failure_fingerprint": fingerprint,
            "same_failure_count": same_failure_count,
        }
        non_retryable = self._blocked_attempt_non_retryable_marker(task)
        node_fault = _node_fault(latest_detail)
        if node_fault is not None and not non_retryable and prior_agent_id.startswith("agent_"):
            # The node failed, not the task: bench the node and give the task
            # its attempt back, whatever the worker labelled the failure.
            reopened = self._requeue_after_node_fault(
                task,
                agent_id=prior_agent_id,
                fault=node_fault,
                fingerprint=fingerprint,
                detail=base_detail,
                now=now,
            )
            return reopened, None
        if not non_retryable and self._attempt_hit_router_outage(task):
            # The hub's model router could not reach any provider during the
            # attempt: the agent never had a model, so the attempt is not the
            # task's to pay for. Wait out the usual backoff, then reopen.
            if parse_time(now) < parse_time(ready_at):
                return None, None
            return self._requeue_after_router_outage(task, detail=base_detail), None
        # A failed repository gate carries the same problem text every time
        # the gate is red, whatever the agent changed; each attempt is new work
        # against the gate output, so only max_attempts bounds it.
        repeated_failure = same_failure_count >= 2 and retry_kind != "work"
        exhausted = task.attempt_count >= task.max_attempts
        must_stop = bool(
            non_retryable or retry_kind == "non_retryable" or repeated_failure or exhausted
        )
        if must_stop:
            incident: Optional[Task] = None
            if retry_kind == "shared_transient" and (repeated_failure or exhausted):
                incident = self._ensure_shared_failure_incident(
                    task,
                    fingerprint=fingerprint,
                    detail=latest_detail,
                )
                base_detail["shared_failure_incident_task_id"] = incident.id
                # The incident helper durably links the victim in metadata.
                # Reload so failure classification cannot overwrite that link
                # with the stale task object supplied to this sweep.
                task = self.get_task(task.id)
            reason = (
                "non_retryable_attempt_failure"
                if non_retryable or retry_kind == "non_retryable"
                else "repeated_identical_attempt_failure"
                if repeated_failure
                else "max attempts"
            )
            target_state, exhausted_detail = self._exhausted_attempt_terminal_transition(
                task,
                {
                    **base_detail,
                    "via": "auto_retry_exhausted",
                    "reason": reason,
                    "manual_repair_required": True,
                    "_suppress_environment_repair": (
                        retry_kind == "shared_transient" or repeated_failure
                    ),
                },
            )
            stopped = self._transition_task_internal(
                task.id,
                target_state,
                "dispatcher.tick",
                exhausted_detail,
            )
            return None, stopped
        if parse_time(now) < parse_time(ready_at):
            return None, None
        detail = {
            **base_detail,
            "reason": (
                "retry after the repository test gate failed"
                if retry_kind == "work"
                else "one bounded cross-worker retry after transient failure"
            ),
        }
        gate_failure = ensure_json_object(latest_detail.get("repository_gate_failure"))
        if retry_kind == "work" and gate_failure:
            # The next attempt's prompt renders this (executor_prompt
            # _repository_gate_failure_section): which tests failed and how.
            gate_metadata = ensure_json_object(self.get_task(task.id).metadata)
            gate_metadata["repository_gate_failure"] = {
                "name": str(gate_failure.get("name") or "")[:200],
                "command": str(gate_failure.get("command") or "")[:500],
                "returncode": gate_failure.get("returncode"),
                "head_sha": str(gate_failure.get("head_sha") or "")[:64],
                "failing_lines": [
                    str(line)[:300]
                    for line in _metadata_string_list(gate_failure.get("failing_lines"))
                ][-30:],
                "output_tail": str(gate_failure.get("output_tail") or "")[-4000:],
                "failed_attempt": int(task.attempt_count or 0),
                "max_attempts": int(task.max_attempts or 0),
                "recorded_at": now,
            }
            self.store.execute(
                "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
                (json_dumps(gate_metadata), now, task.id),
            )
            task = self.get_task(task.id)
        self._record_retry_worker_exclusion(
            task,
            agent_id=prior_agent_id,
            fingerprint=fingerprint,
            retry_kind=retry_kind,
            now=now,
        )
        is_timeout = retry_kind == "timeout"
        if is_timeout and not ensure_json_object(task.metadata).get("plan_first"):
            # mac-timeout-plan: a timed-out task is likely too large for a
            # monolithic run. Instead of retrying blindly, inject plan_first=True
            # so the next executor run decomposes the work instead of repeating it.
            patched_meta = ensure_json_object(task.metadata)
            patched_meta["plan_first"] = True
            self.store.execute(
                "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
                (json_dumps(patched_meta), now, task.id),
            )
            self._record_history(
                task.id,
                "task.timeout_requeued_as_plan",
                "dispatcher.tick",
                TaskState.BLOCKED.value,
                TaskState.BLOCKED.value,
                {**detail, "injected": "plan_first"},
            )
        reopened = self._transition_task_internal(
            task.id,
            TaskState.OPEN.value,
            "dispatcher.tick",
            detail,
        )
        self._record_history(
            task.id,
            "task.auto_reopened",
            "dispatcher.tick",
            TaskState.BLOCKED.value,
            TaskState.OPEN.value,
            detail,
        )
        return reopened, None

    def _prepare_cooperative_integration_task(self, task: Task) -> Task:
        """Attach immutable child outputs before reopening an integration task."""
        metadata = ensure_json_object(task.metadata)
        coordination = ensure_json_object(metadata.get("coordination"))
        if coordination.get("mode") != "cooperative_integration":
            return task
        child_ids = _metadata_string_list(coordination.get("child_task_ids"))
        if not child_ids:
            return task
        outputs: List[JsonDict] = []
        for child_id in child_ids:
            try:
                child = self.get_task(child_id)
            except NotFoundError:
                outputs.append({"task_id": child_id, "status": "missing_task"})
                continue
            child_target = ensure_json_object(
                ensure_json_object(child.metadata).get("review_target")
            )
            evidence_id = str(child_target.get("executor_evidence_id") or "").strip()
            output: JsonDict = {
                "task_id": child.id,
                "title": child.title,
                "state": child.state,
                "executor_evidence_id": evidence_id,
            }
            dependency_resolution = ensure_json_object(
                ensure_json_object(child.metadata).get("dependency_resolution")
            )
            if dependency_resolution:
                output["dependency_resolution"] = dependency_resolution
            if evidence_id:
                try:
                    evidence = self.get_evidence(evidence_id)
                except NotFoundError:
                    output["status"] = "missing_evidence"
                else:
                    manifest = ensure_json_object(
                        ensure_json_object(evidence.metadata).get("verification")
                    )
                    repo = ensure_json_object(manifest.get("repo"))
                    output.update(
                        {
                            "status": "ready",
                            "summary": evidence.summary,
                            "created_by": evidence.created_by,
                            "evidence_type": manifest.get("evidence_type"),
                            "repo": {
                                key: repo.get(key)
                                for key in (
                                    "head_sha",
                                    "base_sha",
                                    "remote_ref",
                                    "remote_url",
                                    "pr_url",
                                    "files_changed",
                                )
                                if repo.get(key) not in (None, "", [])
                            },
                        }
                    )
            else:
                output["status"] = "missing_evidence"
            outputs.append(output)
        coordination["phase"] = "integration"
        coordination["child_outputs"] = outputs
        coordination["integration_contract"] = {
            "required": True,
            "strategy": "merge_each_exact_child_commit",
            "verify_combined_result": True,
            "verify_child_commit_ancestry": True,
        }
        metadata["coordination"] = coordination
        self.store.execute(
            "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
            (json_dumps(metadata), utcnow(), task.id),
        )
        return self.get_task(task.id)

    def _unblock_ready_tasks(
        self,
        *,
        limit: int = 100,
        cursor: Optional[str] = None,
    ) -> JsonDict:
        limit_value = max(1, min(int(limit), 1000))
        clauses = ["state IN (?, ?)"]
        params: List[Any] = [TaskState.WAITING.value, TaskState.BLOCKED.value]
        decoded = self._decode_scan_cursor(cursor, "blocked-tasks")
        if decoded is not None:
            updated_at, task_id = decoded
            clauses.append("(updated_at > ? OR (updated_at = ? AND id > ?))")
            params.extend([updated_at, updated_at, task_id])
        params.append(limit_value + 1)
        rows = self.store.query_all(
            "SELECT * FROM tasks WHERE %s ORDER BY updated_at, id LIMIT ?" % " AND ".join(clauses),
            tuple(params),
        )
        has_more = len(rows) > limit_value
        rows = rows[:limit_value]
        unblocked: List[Task] = []
        for row in rows:
            task = self._task_from_row(row)
            try:
                manual_repair = self._blocked_task_requires_manual_repair(task)
                # Supervision is a statement about a dependency, not about this
                # task, so it must not outlive the condition that caused it. A
                # terminal dependency can be replaced or force-completed later;
                # when that happens the supervised task has to become runnable
                # again. Without this, keeping the marker across restarts (which
                # is what makes an all_settled parent able to settle) would trade
                # one permanent stall for another.
                supervised = self._dependency_supervision_is_recoverable(task)
                dependency_ids = self._canonical_task_dependency_ids(task.id)
                if (
                    dependency_ids
                    and self._dependencies_satisfied(
                        task,
                        dependency_ids=dependency_ids,
                    )
                    and (not manual_repair or supervised)
                ):
                    settlement = self._dependency_settlement(task, dependency_ids=dependency_ids)
                    if supervised:
                        task = self._clear_dependency_supervision(task)
                    task = self._prepare_cooperative_integration_task(task)
                    task = self._record_dependency_settlement(task, settlement)
                    detail: JsonDict = {"reason": "dependencies satisfied"}
                    if not settlement["all_inputs_present"]:
                        # The parent is being released over dependencies that
                        # produced nothing. Say so here rather than leaving
                        # "dependencies satisfied" to imply inputs exist.
                        detail["reason"] = "dependencies settled without output"
                        detail["settled_without_output"] = settlement["settled_without_output"]
                        detail["dependency_settlement"] = settlement
                    unblocked.append(
                        self._transition_task_internal(
                            task.id,
                            TaskState.OPEN.value,
                            "dispatcher",
                            detail,
                        )
                    )
                    if not settlement["all_inputs_present"]:
                        try:
                            self.record_log(
                                "task.dependencies_settled_without_output",
                                level="warning",
                                subject_type="task",
                                subject_id=task.id,
                                detail={
                                    "task_id": task.id,
                                    "settled_without_output": settlement["settled_without_output"],
                                    "join": settlement["join"],
                                },
                            )
                        except Exception:  # noqa: BLE001 - diagnostic only
                            pass
                elif task.state == TaskState.BLOCKED.value and dependency_ids and not manual_repair:
                    # One-way compatibility migration for ledgers created
                    # before dependency waits had their own state.
                    self._transition_task_internal(
                        task.id,
                        TaskState.WAITING.value,
                        "dispatcher",
                        {
                            "reason": "waiting_on_dependencies",
                            "blocked_by_task_ids": dependency_ids,
                            "legacy_state_migration": True,
                        },
                    )
            except Exception as exc:  # noqa: BLE001 - isolate corrupt blocked rows.
                try:
                    self.record_log(
                        "task.unblock.failed",
                        layer="control_plane",
                        source="dispatcher",
                        level="error",
                        subject_type="task",
                        subject_id=task.id,
                        detail={"task_id": task.id, "error": str(exc)},
                    )
                except Exception:
                    pass
        next_cursor = (
            self._encode_scan_cursor(
                "blocked-tasks",
                str(rows[-1]["updated_at"]),
                str(rows[-1]["id"]),
            )
            if has_more and rows
            else None
        )
        return {
            "tasks": unblocked,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }

    def _unblock_ready_sweep_page(self, *, limit: int) -> JsonDict:
        claim = self.reconciliation.claim("blocked-task-sweep")
        if claim is None:
            return {
                "tasks": [],
                "next_cursor": None,
                "has_more": False,
                "skipped": "lease_held",
            }
        try:
            result = self._unblock_ready_tasks(
                limit=limit,
                cursor=claim.cursor,
            )
        except Exception:
            self.reconciliation.abandon(claim)
            raise
        self.reconciliation.complete(claim, cursor=result.get("next_cursor"))
        return result

    def _auto_retry_blocked_attempts(
        self,
        *,
        limit: int = 100,
        cursor: Optional[str] = None,
    ) -> JsonDict:
        limit_value = max(1, min(int(limit), 1000))
        clauses = ["state = ?", "attempt_count > 0"]
        params: List[Any] = [TaskState.BLOCKED.value]
        decoded = self._decode_scan_cursor(cursor, "blocked-attempt-retries")
        if decoded is not None:
            updated_at, task_id = decoded
            clauses.append("(updated_at > ? OR (updated_at = ? AND id > ?))")
            params.extend([updated_at, updated_at, task_id])
        params.append(limit_value + 1)
        rows = self.store.query_all(
            "SELECT * FROM tasks WHERE %s ORDER BY updated_at, id LIMIT ?" % " AND ".join(clauses),
            tuple(params),
        )
        has_more = len(rows) > limit_value
        rows = rows[:limit_value]
        now = utcnow()
        reopened: List[Task] = []
        exhausted: List[Task] = []
        for row in rows:
            task = self._task_from_row(row)
            try:
                reopened_task, exhausted_task = self._auto_retry_blocked_attempt_task(
                    task,
                    now=now,
                )
            except Exception as exc:  # noqa: BLE001 - isolate corrupt blocked rows.
                try:
                    self.record_log(
                        "task.auto_retry.failed",
                        layer="control_plane",
                        source="dispatcher.tick",
                        level="error",
                        subject_type="task",
                        subject_id=task.id,
                        detail={"task_id": task.id, "error": str(exc)},
                    )
                except Exception:
                    pass
                continue
            if reopened_task is not None:
                reopened.append(reopened_task)
            if exhausted_task is not None:
                exhausted.append(exhausted_task)
        next_cursor = (
            self._encode_scan_cursor(
                "blocked-attempt-retries",
                str(rows[-1]["updated_at"]),
                str(rows[-1]["id"]),
            )
            if has_more and rows
            else None
        )
        return {
            "tasks": reopened,
            "exhausted": exhausted,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }

    def _auto_retry_blocked_attempts_sweep_page(self, *, limit: int) -> JsonDict:
        claim = self.reconciliation.claim("blocked-attempt-retry-sweep")
        if claim is None:
            return {
                "tasks": [],
                "exhausted": [],
                "next_cursor": None,
                "has_more": False,
                "skipped": "lease_held",
            }
        try:
            result = self._auto_retry_blocked_attempts(
                limit=limit,
                cursor=claim.cursor,
            )
        except Exception:
            self.reconciliation.abandon(claim)
            raise
        self.reconciliation.complete(claim, cursor=result.get("next_cursor"))
        return result

    # mac-5ayd: cap the working set per dispatch batch. Loading 100k OPEN
    # tasks into Python to sort+round-robin is wasteful and grows linearly
    # with backlog. 500 is above the largest supported tick batch while
    # remaining below the point where the Python sort cost is noticeable.
    _DISPATCH_TASK_WINDOW = 500
    _DISPATCH_PRIORITY_AGING_SECONDS = 24 * 60 * 60
    # Dispatch classes are deliberately a soft, work-conserving lane rather
    # than a permanently idle worker reservation.  A recovery task wins over
    # ordinary backlog as soon as any worker becomes available; when no
    # recovery is queued, every worker remains usable for normal work.
    _DISPATCH_CLASS_PRIORITY_STRIDE = 1_000_000
    _DISPATCH_CLASS_RANKS = {
        "background": -1,
        "normal": 0,
        "recovery": 1,
        "urgent": 2,
    }
    _DISPATCH_DUE_AGING_SECONDS = 4 * 60 * 60
    _DISPATCH_DUE_BONUS_CAP = 24
    _DISPATCH_SKIP_LOG_LIMIT = 25
    # mac page-prefix fairness: within a single (tenant, project) group, a burst
    # of candidates sharing a common id / page-cursor prefix can otherwise fill
    # the whole scan window and starve later prefixes indefinitely. Bucketing by
    # the leading *N* characters of the page-prefix key and round-robining across
    # buckets gives every prefix a claim slot each cycle while preserving each
    # bucket's internal (priority, age) order. Width 2 is a safe default; a
    # single bucket (all keys share the prefix, or the width covers the whole
    # key) leaves ordering unchanged. Overridable via env for operators who need
    # coarser/finer rotation, but never below a floor of 1 character.
    _DISPATCH_PAGE_PREFIX_WIDTH = 2

    def _dispatch_ordered_tasks(self, *, project: Optional[str] = None) -> List[Task]:
        # Allocator v2 owns ordering.  Feed it the complete OPEN population;
        # the retired priority/oldest dual windows could permanently hide the
        # stable middle of a large backlog behind incompatible edge windows.
        return self._dispatch_candidate_tasks(project=project)

    def _interleave_tasks_by_project(
        self,
        tasks: List[Task],
        now: str,
    ) -> List[Task]:
        """Round-robin a tenant's candidates across projects.

        Projects sharing a tenant otherwise contend on a single
        (priority, age) order, so one project flooding high-priority tasks
        starves its siblings for up to the aging period. Interleaving gives
        every project with ready work a claim slot each cycle; within a
        project the candidates are rotated across page-prefix buckets (via
        :meth:`_rotate_by_page_prefix`) so one id/page-cursor prefix cannot
        monopolize the claim window either, while the (priority, age) order is
        preserved within each bucket.
        """
        projects: Dict[str, List[Task]] = {}
        for task in tasks:
            projects.setdefault(task.project or "", []).append(task)
        for name, project_tasks in projects.items():
            # Within each (tenant, project) group rotate fairly across
            # page-prefix buckets so one id/page-cursor prefix cannot
            # monopolize the claim window. The helper preserves the sorted
            # (priority, age) order within a bucket and is a no-op when only a
            # single prefix bucket is present, so the group head still leads on
            # (priority, age).
            projects[name] = self._rotate_by_page_prefix(project_tasks, now)
        project_order = sorted(
            projects,
            key=lambda name: (
                *self._dispatch_task_sort_key(projects[name][0], now),
                name,
            ),
        )
        ordered: List[Task] = []
        while any(projects.values()):
            for name in project_order:
                if projects[name]:
                    ordered.append(projects[name].pop(0))
        return ordered

    @staticmethod
    def _page_prefix_key(task: Task, width: int) -> str:
        """Derive the page-prefix bucket key for *task*.

        The key is the leading *width* characters of the task's page cursor
        (when present) or its id, mirroring how paginated scans group work by
        id/page-cursor prefix. Pure and side-effect free so both the dispatch
        and review paths can reuse the same bucketing.
        """
        source = getattr(task, "page_cursor", None) or task.id or ""
        return source[:width]

    def _rotate_by_page_prefix(
        self,
        tasks: List[Task],
        now: str,
        width: Optional[int] = None,
    ) -> List[Task]:
        """Round-robin an ordered candidate list across page-prefix buckets.

        Candidates sharing a common id / page-cursor prefix can otherwise
        monopolize the scan window while later prefixes never get serviced.
        Bucketing by the leading *width* characters of the page-prefix key and
        round-robining across buckets gives every prefix a claim slot each
        cycle; within a bucket the (priority, age) order is preserved.

        The helper is pure and side-effect free (it never mutates *tasks*) so
        both the dispatch and review paths can reuse it. When only one prefix
        bucket exists the output order is identical to the sorted input, so the
        rotation is a no-op for single-prefix groups.
        """
        prefix_width = (
            width
            if width is not None
            else _int_env(
                "MAC_DISPATCH_PAGE_PREFIX_WIDTH",
                self._DISPATCH_PAGE_PREFIX_WIDTH,
                minimum=1,
            )
        )
        buckets: Dict[str, List[Task]] = {}
        for task in tasks:
            buckets.setdefault(self._page_prefix_key(task, prefix_width), []).append(task)
        for bucket_tasks in buckets.values():
            bucket_tasks.sort(key=lambda item: self._dispatch_task_sort_key(item, now))
        bucket_order = sorted(
            buckets,
            key=lambda prefix: (
                *self._dispatch_task_sort_key(buckets[prefix][0], now),
                prefix,
            ),
        )
        ordered: List[Task] = []
        while any(buckets.values()):
            for prefix in bucket_order:
                if buckets[prefix]:
                    ordered.append(buckets[prefix].pop(0))
        return ordered

    def _dispatch_candidate_tasks(self, *, project: Optional[str] = None) -> List[Task]:
        """Return every unowned OPEN task to the authoritative allocator."""
        where = ["state = ?", "owner_agent_id IS NULL", "lease_id IS NULL"]
        params: List[Any] = [TaskState.OPEN.value]
        if project is not None:
            where.append("project = ?")
            params.append(project)
        where_sql = " AND ".join(where)
        rows = self.store.query_all(
            "SELECT * FROM tasks WHERE %s ORDER BY priority DESC, created_at, id" % where_sql,
            tuple(params),
        )
        return [self._task_from_row(row) for row in rows]

    def _dispatch_task_sort_key(
        self,
        task: Task,
        now: Optional[str] = None,
    ) -> Tuple[int, float, str, str]:
        age_bonus = self._dispatch_priority_age_bonus(task, now or utcnow())
        due_bonus = self._dispatch_due_bonus(task, now or utcnow())
        dispatch_class = self._dispatch_class(task)
        class_rank = self._DISPATCH_CLASS_RANKS[dispatch_class]
        effective_priority = (
            int(task.priority or 0)
            + age_bonus
            + due_bonus
            + class_rank * self._DISPATCH_CLASS_PRIORITY_STRIDE
        )
        return (-effective_priority, 0.0, task.created_at, task.id)

    def _dispatch_class(self, task: Task) -> str:
        metadata = ensure_json_object(task.metadata)
        value = str(metadata.get("dispatch_class") or "").strip().lower()
        if value in self._DISPATCH_CLASS_RANKS:
            return value
        origin = ensure_json_object(metadata.get("origin"))
        if str(origin.get("type") or "").strip().endswith("_prerequisite"):
            return "recovery"
        return "normal"

    def _dispatch_due_bonus(self, task: Task, now: str) -> int:
        metadata = ensure_json_object(task.metadata)
        raw_due_at = str(metadata.get("due_at") or metadata.get("deadline_at") or "").strip()
        if not raw_due_at:
            return 0
        try:
            overdue_seconds = (parse_time(now) - parse_time(raw_due_at)).total_seconds()
        except Exception:  # noqa: BLE001 - malformed hints must not block work.
            return 0
        if overdue_seconds < 0:
            return 0
        step_seconds = _int_env(
            "MAC_DISPATCH_DUE_AGING_SECONDS",
            self._DISPATCH_DUE_AGING_SECONDS,
            minimum=60,
        )
        return min(
            self._DISPATCH_DUE_BONUS_CAP,
            1 + int(overdue_seconds // step_seconds),
        )

    def _dispatch_priority_age_bonus(self, task: Task, now: str) -> int:
        step_seconds = _int_env(
            "MAC_DISPATCH_PRIORITY_AGING_SECONDS",
            self._DISPATCH_PRIORITY_AGING_SECONDS,
            minimum=60,
        )
        try:
            age_seconds = (parse_time(now) - parse_time(task.created_at)).total_seconds()
        except Exception:  # noqa: BLE001 - corrupt timestamps should not block dispatch.
            return 0
        return max(0, int(age_seconds // step_seconds))

    def _active_break_glass_authorization(
        self,
        task_id: str,
        agent_id: Optional[str] = None,
        *,
        now: Optional[str] = None,
    ) -> Optional[BreakGlassAuthorization]:
        current = now or utcnow()
        clauses = ["task_id = ?", "status = 'active'", "expires_at > ?"]
        params: List[Any] = [task_id, current]
        if agent_id is not None:
            clauses.append("agent_id = ?")
            params.append(agent_id)
        row = self.store.query_one(
            "SELECT * FROM task_break_glass_authorizations WHERE %s "
            "ORDER BY created_at DESC LIMIT 1" % " AND ".join(clauses),
            tuple(params),
        )
        return self._break_glass_authorization_from_row(row) if row is not None else None

    def _claimed_break_glass_authorization(
        self, task_id: str, agent_id: str, lease_id: str
    ) -> Optional[BreakGlassAuthorization]:
        row = self.store.query_one(
            """
            SELECT * FROM task_break_glass_authorizations
            WHERE task_id = ? AND agent_id = ? AND lease_id = ? AND status = 'claimed'
            ORDER BY claimed_at DESC LIMIT 1
            """,
            (task_id, agent_id, lease_id),
        )
        return self._break_glass_authorization_from_row(row) if row is not None else None

    def _project_declared_egress(self, project: Optional[str]) -> JsonDict:
        """The sandbox egress a project's OPERATOR declared, or {} if none.

        Read from ``projects.metadata.egress_contract`` — control-plane state an
        operator sets with ``mac project egress grant``. Deliberately NOT read
        from the repository's own contract: ``project_repositories`` loads that
        from ``.mac/project.yaml`` inside the checkout, so anything declared
        there is repo content, mutable by anyone who can open a pull request,
        and belongs in the untrusted ``derived`` tier rather than this one.

        Hosts are re-validated here rather than trusted from storage. The
        renderer builds policy YAML by concatenation, so a malformed host is a
        policy-injection vector no matter how it got into the database; a bad
        entry is dropped and the rest still apply.
        """
        name = str(project or "").strip()
        if not name:
            return {}
        row = self.store.query_one("SELECT metadata FROM projects WHERE name = ?", (name,))
        if row is None:
            return {}
        block = ensure_json_object(
            ensure_json_object(json_loads(row["metadata"], {})).get("egress_contract")
        )
        raw_hosts = block.get("hosts")
        if not isinstance(raw_hosts, list):
            return {}
        from mac.sandbox_egress import normalize_host

        hosts: List[str] = []
        for candidate in raw_hosts:
            host = normalize_host(candidate)
            if host is not None and host not in hosts:
                hosts.append(host)
        if not hosts:
            return {}
        projected: JsonDict = {"hosts": hosts, "source": "project"}
        reason = str(block.get("reason") or "").strip()
        if reason:
            projected["reason"] = reason
        return projected

    def coding_policy(self) -> JsonDict:
        """The hub's ordered coding-CLI list and model settings, for workers."""
        from mac.coding_agent import hub_coding_policy

        return hub_coding_policy(os.environ)

    def _assignment_task_payload(self, task: Task, lease: Lease) -> JsonDict:
        """Attach a lease-bound host authorization to an in-memory assignment.

        This transient projection is the only task document the executor trusts
        for host execution.  The durable task metadata remains unchanged.
        """

        payload = task.to_dict()
        metadata = ensure_json_object(payload.get("metadata"))
        runtime = ensure_json_object(metadata.get("runtime"))
        # Strip caller-controlled lookalikes even when no authorization exists.
        runtime.pop("break_glass_authorization", None)
        if runtime:
            metadata["runtime"] = runtime
        else:
            metadata.pop("runtime", None)
        # Sandbox egress is PROJECT policy, projected here, never carried on the
        # durable task. Two reasons this is the right home for it:
        #
        #   * Ownership. `metadata.egress_contract` on a task is written by
        #     whoever created the task -- any hub credential. Declaring it on the
        #     project instead makes the `hub_declared` trust tier mean what its
        #     name says: an operator approved these hosts, not "a task author
        #     asked for them". The stale value is stripped exactly like
        #     break_glass_authorization above, so a task cannot smuggle one.
        #   * Reach. A repository has one egress contract and many tasks -- the
        #     Aviation project alone has hundreds. Projecting at assignment time
        #     applies the declaration to every task, including those created
        #     before it existed, instead of only to new ones.
        metadata.pop("egress_contract", None)
        declared_egress = self._project_declared_egress(task.project)
        if declared_egress:
            metadata["egress_contract"] = declared_egress
        # Publication is resolved by the hub from task/project/fleet policy at
        # assignment time. Native executors cannot safely reconstruct project
        # policy from the task's durable metadata, and must not interpret a
        # model-written preliminary manifest as an opt-out.
        runtime = ensure_json_object(metadata.get("runtime"))
        runtime["publication_target"] = self._default_publication_target(task)
        # The fleet's ordered coding-CLI list (and its model settings) is hub
        # configuration, projected the same way: a task cannot carry its own,
        # and every attempt runs on the hub's current list.
        runtime["coding_policy"] = self.coding_policy()
        metadata["runtime"] = runtime
        payload["metadata"] = metadata
        authorization = self._claimed_break_glass_authorization(task.id, lease.agent_id, lease.id)
        if authorization is None:
            return payload
        runtime = ensure_json_object(metadata.get("runtime"))
        runtime["break_glass_authorization"] = authorization.to_dict()
        metadata["runtime"] = runtime
        payload["metadata"] = metadata
        return payload

    def _consume_break_glass_authorizations(
        self,
        conn: Any,
        *,
        task_id: str,
        lease_id: Optional[str],
        now: str,
    ) -> None:
        if not lease_id:
            return
        conn.execute(
            """
            UPDATE task_break_glass_authorizations
            SET status = 'consumed', consumed_at = ?
            WHERE task_id = ? AND lease_id = ? AND status = 'claimed'
            """,
            (now, task_id, lease_id),
        )

    def _task_dispatch_held(self, task: Task) -> bool:
        """True when a task is staged or inside a bounded retry backoff.

        Set via metadata ``no_dispatch: true`` (e.g. ``mac task create
        --no-dispatch``) so a backlog — a freshly-onboarded project's tickets,
        or operator handoff notes — can be filed WITHOUT the loop-mode fleet
        auto-claiming it. The hold only blocks autonomous claim and hides the
        task from the ready queue; an operator can still start it explicitly
        (``mac task claim`` / ``mac task start``). This is the first-class
        replacement for abusing a sentinel ``required_capabilities`` value.
        """
        metadata = ensure_json_object(task.metadata)
        if metadata.get("no_dispatch"):
            return True
        semantic_retry = ensure_json_object(metadata.get("semantic_retry"))
        not_before = str(semantic_retry.get("not_before") or "").strip()
        if not_before and semantic_retry.get("status") == "scheduled":
            try:
                return parse_time(utcnow()) < parse_time(not_before)
            except (TypeError, ValueError):
                # Corrupt controller metadata must not strand useful work.
                return False
        return False

    def _project_dispatch_paused(self, project: Optional[str]) -> bool:
        """True when the task's project is explicitly dispatch-PAUSED.

        Per-project onboarding gate: a newly-created project can be staged
        (``mac project create`` defaults to paused; ``mac project activate``
        releases it) so its tickets don't auto-dispatch until the operator
        turns the project on. IMPLICIT projects (no ``projects`` row — the case
        for the live fleet's default project) are never paused, so existing
        autonomous behavior is unchanged. Only projects with a record carrying
        ``metadata.dispatch_paused`` are held.
        """
        if not project:
            return False
        try:
            rec = self.get_project_record(project)
        except NotFoundError:
            return False
        except Exception:  # noqa: BLE001 — never let a lookup error block dispatch
            return False
        return bool(ensure_json_object(rec.metadata).get("dispatch_paused"))

    @staticmethod
    def _advisory_health_dispatch_ready(agent: Agent) -> bool:
        """Accept health that is safe for coding-task dispatch.

        A gateway/model probe may report a degraded startup self-test while
        also proving that it has no blocking problems. ``deploy-mac-fleet.sh``
        already releases such an agent (``release_health_ready``); the
        allocator has to agree, or an advisory condition — a gateway probe
        that cannot find a stale sandbox, say — benches an otherwise idle,
        authenticated worker, and does it to every worker at once.
        """

        return advisory_health_dispatch_ready(
            agent.health_status, ensure_json_object(agent.resources), agent_id=agent.id
        )

    def _available_agents(self) -> List[Agent]:
        # Health is filtered in Python rather than SQL: the advisory verdict
        # lives inside the resources JSON, whose accessors differ per backend.
        rows = self.store.query_all(
            """
            SELECT a.* FROM agents a
            JOIN machines m ON m.id = a.machine_id
            WHERE a.status IN (?, ?) AND a.health_status IN (?, ?) AND m.trusted = 1
            ORDER BY a.last_seen_at DESC, a.id
            """,
            (
                AgentStatus.IDLE.value,
                AgentStatus.BUSY.value,
                HealthStatus.HEALTHY.value,
                HealthStatus.DEGRADED.value,
            ),
        )
        agents = [self._agent_from_row(row) for row in rows]
        return [agent for agent in agents if self._advisory_health_dispatch_ready(agent)]

    def _coordination_related_task_ids(self, task: Task) -> set[str]:
        """Return the durable task family used for cooperative separation."""
        metadata = ensure_json_object(task.metadata)
        coordination = ensure_json_object(metadata.get("coordination"))
        if coordination.get("require_distinct_agent") is not True:
            return set()
        relationships = ensure_json_object(metadata.get("relationships"))
        parent_id = str(
            relationships.get("parent_task_id") or metadata.get("parent_task_id") or task.id
        ).strip()
        related_ids = {parent_id}
        if parent_id == task.id:
            related_ids.update(_metadata_string_list(coordination.get("child_task_ids")))
            related_ids.update(_metadata_string_list(relationships.get("child_task_ids")))
        else:
            try:
                parent = self.get_task(parent_id)
            except NotFoundError:
                parent = None
            if parent is not None:
                parent_metadata = ensure_json_object(parent.metadata)
                parent_relationships = ensure_json_object(parent_metadata.get("relationships"))
                parent_coordination = ensure_json_object(parent_metadata.get("coordination"))
                related_ids.update(
                    _metadata_string_list(parent_relationships.get("child_task_ids"))
                )
                related_ids.update(_metadata_string_list(parent_coordination.get("child_task_ids")))
        return related_ids

    def _coordination_excluded_agent_ids(self, task: Task) -> set[str]:
        """Agents that meaningfully participated in a cooperative task family.

        Decomposed children and the final integration pass require distinct
        executors.  Lease history is the durable source of participation: it
        survives task handoff, unlike ``owner_agent_id``.

        Expired leases are *excluded* from the participation set: an expired
        lease means the agent went offline / crashed mid-attempt (it never
        produced a result to keep the reviewer independent from), so counting
        it as durable participation permanently burns that agent for the whole
        family after a mere crash.  In a finite agent pool, accumulated expired
        leases ratchet every family into a permanent no-eligible-agent deadlock
        that buys nothing — a re-attempt by the crashed agent is strictly better
        than a task that can never run again.  Only active/renewed/released
        leases (a real, completed-or-in-flight attempt) count.
        """
        related_ids = self._coordination_related_task_ids(task)
        if not related_ids:
            return set()
        placeholders = ",".join("?" for _ in related_ids)
        rows = self.store.query_all(
            "SELECT DISTINCT agent_id FROM leases "
            "WHERE task_id IN (%s) AND status != ?" % placeholders,
            (*sorted(related_ids), LeaseStatus.EXPIRED.value),
        )
        return {str(row["agent_id"]) for row in rows if row["agent_id"]}

    def _prior_attempt_agent_ids(self, task: Task) -> set[str]:
        """Agents that have already attempted THIS task and not finished it.

        A re-dispatch means the previous attempt did not succeed. Sending it
        back to the same agent repeats whatever was wrong with that host, and
        the ledger shows this happening: on 2026-08-06 task_c5407d23 burned
        three attempts on agent_rocky and task_30929062 burned three on
        agent_jordanh-worker6 -- the latter unpinned, failing because it could
        not reach another host's filesystem, which no amount of retrying there
        would fix.

        This feeds ``avoid_agent_ids``, which the allocator treats as a SOFT
        preference (``prior_participation`` in its sort key), not an exclusion.
        That distinction is the whole design: hard-excluding a failed agent
        would ratchet a finite pool into a no-eligible-agent deadlock, which
        ``_coordination_excluded_agent_ids`` already learned the hard way. A
        retry on the same agent is worse than a retry elsewhere and far better
        than a task that can never run again, so this only reorders.

        Expired leases count here, unlike in the coordination set: an agent
        that crashed mid-attempt is exactly the host a retry should prefer to
        avoid, and preferring is all this does.
        """
        rows = self.store.query_all(
            "SELECT DISTINCT agent_id FROM leases WHERE task_id = ?",
            (task.id,),
        )
        return {str(row["agent_id"]) for row in rows if row["agent_id"]}

    def _agent_available_for(
        self, agent: Agent, task: Task, *, allow_cooperative_reuse: bool = False
    ) -> bool:
        available, _reason = self._agent_availability_for_task(
            agent, task, allow_cooperative_reuse=allow_cooperative_reuse
        )
        return available

    def _claim_snapshot_ineligibility_reason(
        self,
        *,
        agent: Agent,
        task: Task,
        machine: Machine,
        active_count: int,
        project_paused: bool,
        break_glass: Optional[BreakGlassAuthorization],
        required_runtime_digest: Optional[str],
        role_reason: Optional[str],
    ) -> Optional[str]:
        """Evaluate mutable claim predicates from transaction-locked rows.

        Candidate generation remains an optimization. This is the authority
        immediately before lease INSERT, covering the state that can change
        after a dispatcher preflight (agent drain/status/capabilities/runtime,
        task/project holds, and machine trust/resource/tenant policy).
        """
        if agent.deleted_at:
            return "agent_deleted"
        if agent.status not in {AgentStatus.IDLE.value, AgentStatus.BUSY.value}:
            return "agent_status_unavailable"
        if not self._advisory_health_dispatch_ready(agent):
            return "agent_health_unavailable"
        if not self.directives.agent_policy_ready(agent.id):
            return "directive_policy_unacknowledged"
        if active_count >= 1:
            return "agent_capacity_full"
        if not machine.trusted:
            return "machine_untrusted"
        if not self._machine_allows_tenant(machine, self._task_tenant_id(task)):
            return "machine_tenant_not_allowed"
        if metadata_declares_read_only_report_repository(
            task.metadata
        ) and not agent_has_read_only_report_repository_executor(agent.resources):
            return "report_repository_executor_missing"

        break_glass_active = break_glass is not None and break_glass.agent_id == agent.id
        if self._task_dispatch_held(task) and not break_glass_active:
            return "dispatch_held"
        if project_paused and not break_glass_active:
            return "project_dispatch_paused"
        if agent.dispatch_hold and not break_glass_active:
            return "agent_dispatch_held"

        metadata = ensure_json_object(task.metadata)
        excluded = (
            {str(value) for value in metadata.get("excluded_agent_ids", []) if str(value)}
            if isinstance(metadata.get("excluded_agent_ids"), list)
            else set()
        )
        if agent.id in excluded:
            return "explicit_agent_excluded"
        target_agent_id = str(metadata.get("target_agent_id") or "").strip()
        if target_agent_id and target_agent_id != agent.id:
            return "target_agent_id_mismatch"
        target_agent_name = str(metadata.get("target_agent_name") or "").strip()
        if target_agent_name and target_agent_name != agent.name:
            return "target_agent_name_mismatch"
        if required_runtime_digest and agent.running_digest != required_runtime_digest:
            return "runtime_digest_mismatch"

        if break_glass_active:
            return None
        if not self._agent_resources_satisfy(agent, machine, task):
            return "agent_resources_insufficient"
        if not self._agent_has_clean_managed_repository_source(agent, task):
            return "repository_source_dirty"
        if not self._agent_has_repository_commands(agent, task):
            return "repository_commands_missing"
        coding_route_ok, coding_route_reason = self._agent_has_verified_coding_route(agent, task)
        if not coding_route_ok:
            return coding_route_reason
        if role_reason is not None:
            return role_reason
        return None

    def _claim_snapshot_v2_ineligibility_reason(
        self,
        *,
        agent: Agent,
        task: Task,
        machine: Machine,
        active_count: int,
        project_registered: bool,
        project_paused: bool,
        break_glass: Optional[BreakGlassAuthorization],
        role_reason: Optional[str],
        allow_retry_exclusion_reuse: bool = False,
    ) -> Optional[str]:
        """Re-check only allocator-v2 hard constraints under transaction locks.

        Repository cleanliness, command inventories, directive
        acknowledgements, role/persona preferences, and worker-local metadata
        filters are observations or placement preferences.  They may influence
        ranking and repair work, but they cannot strand otherwise runnable work
        at the final lease boundary.

        The coding-route proof is not a preference: a worker without a fresh
        proof for a CLI on the hub's list cannot run repository work at all.
        It is enforced here and in the allocator's pair evaluation through the
        same :mod:`mac.coding_route_gate`, so the allocator never proposes a
        pair this check would refuse unless the proof expired in between.
        """

        if agent.deleted_at:
            return "agent_deleted"
        if agent.status not in {AgentStatus.IDLE.value, AgentStatus.BUSY.value}:
            return "agent_status_unavailable"
        if not self._advisory_health_dispatch_ready(agent):
            return "agent_health_unavailable"
        # MacWorker owns one synchronous executor, and allocator-v2 snapshots
        # deliberately expose exactly one slot.  Do not reinterpret a
        # worker-advertised capacity value at the transactional boundary: it
        # can be stale, malformed, or larger than the executor can renew.
        if active_count >= 1:
            return "agent_capacity_full"
        if not machine.trusted:
            return "machine_untrusted"
        if not self._machine_allows_tenant(machine, self._task_tenant_id(task)):
            return "machine_tenant_not_allowed"
        break_glass_active = break_glass is not None and break_glass.agent_id == agent.id
        if not project_registered and not break_glass_active:
            return "task_project_unregistered"
        if self._task_dispatch_held(task) and not break_glass_active:
            return "dispatch_held"
        if project_paused and not break_glass_active:
            return "project_dispatch_paused"
        if agent.dispatch_hold and not break_glass_active:
            return "agent_dispatch_held"

        if break_glass_active:
            return None

        metadata = ensure_json_object(task.metadata)
        excluded = (
            {str(value) for value in metadata.get("excluded_agent_ids", []) if str(value)}
            if isinstance(metadata.get("excluded_agent_ids"), list)
            else set()
        )
        if not allow_retry_exclusion_reuse:
            retry_excluded = metadata.get("retry_excluded_agent_ids")
            if isinstance(retry_excluded, list):
                excluded.update(str(value) for value in retry_excluded if str(value))
        if agent.id in excluded:
            return "explicit_agent_excluded"
        target_agent_id = str(metadata.get("target_agent_id") or "").strip()
        if target_agent_id and target_agent_id != agent.id:
            return "target_agent_id_mismatch"
        target_agent_name = str(metadata.get("target_agent_name") or "").strip()
        if target_agent_name and target_agent_name != agent.name:
            return "target_agent_name_mismatch"

        if not self._agent_resources_satisfy(agent, machine, task):
            return "agent_resources_insufficient"
        if not set(task.required_capabilities).issubset(set(agent.capabilities)):
            return "capabilities_missing"
        # The allocator applied the same gate when it chose this pair, so this
        # refuses only a proof that went stale between snapshot and claim.
        coding_route_ok, coding_route_reason = self._agent_has_verified_coding_route(agent, task)
        if not coding_route_ok:
            return coding_route_reason
        if role_reason is not None:
            return role_reason
        return None

    def _task_required_runtime_digest_in_transaction(
        self,
        conn: Any,
        task: Task,
    ) -> Optional[str]:
        metadata = ensure_json_object(task.metadata)
        runtime_meta = ensure_json_object(metadata.get("runtime"))
        for value in (
            runtime_meta.get("required_runtime_digest"),
            runtime_meta.get("runtime_digest"),
            runtime_meta.get("base_runtime_digest"),
            metadata.get("required_runtime_digest"),
            metadata.get("runtime_digest"),
        ):
            digest = str(value or "").strip()
            if digest:
                return digest
        runtime_id = str(
            runtime_meta.get("runtime_environment_id")
            or runtime_meta.get("required_runtime_environment_id")
            or metadata.get("runtime_environment_id")
            or metadata.get("required_runtime_environment_id")
            or ""
        ).strip()
        if not runtime_id:
            return None
        conn.execute(
            "UPDATE runtime_environments SET updated_at = updated_at WHERE id = ?",
            (runtime_id,),
        )
        row = conn.execute(
            "SELECT digest FROM runtime_environments WHERE id = ?",
            (runtime_id,),
        ).fetchone()
        return str(row["digest"]) if row is not None else "__unknown_runtime_digest__"

    def _claim_role_ineligibility_reason_in_transaction(
        self,
        conn: Any,
        *,
        agent: Agent,
        task: Task,
        machine: Machine,
    ) -> Optional[str]:
        """Connection-local role, hardware, and soul eligibility snapshot."""

        def locked_role_by_id(role_id: str) -> Optional[Any]:
            conn.execute(
                "UPDATE agent_roles SET updated_at = updated_at WHERE id = ?",
                (role_id,),
            )
            return conn.execute("SELECT * FROM agent_roles WHERE id = ?", (role_id,)).fetchone()

        def locked_global_role(role_id_or_slug: str) -> Optional[Any]:
            row = conn.execute(
                "SELECT id FROM agent_roles WHERE id = ?",
                (role_id_or_slug,),
            ).fetchone()
            if row is None:
                row = conn.execute(
                    "SELECT id FROM agent_roles WHERE slug = ? AND tenant_id IS NULL",
                    (role_id_or_slug,),
                ).fetchone()
            return locked_role_by_id(str(row["id"])) if row is not None else None

        metadata = ensure_json_object(task.metadata)
        required_role = str(metadata.get("required_role") or "").strip()
        target_role = locked_global_role(required_role) if required_role else None
        if required_role and target_role is None:
            return "required_role_unknown"

        bound_role = locked_role_by_id(agent.role_id) if agent.role_id else None
        if agent.role_id and bound_role is None:
            return "agent_role_unknown"
        if required_role:
            if bound_role is not None:
                if str(bound_role["slug"]) != required_role:
                    return "required_role_mismatch"
            else:
                target_caps = set(json_loads(target_role["required_capabilities"], []))
                if not target_caps.issubset(set(agent.capabilities)):
                    return "required_role_capabilities_missing"

        role_required_caps: set = set()
        if bound_role is not None:
            role_required_caps = set(json_loads(bound_role["required_capabilities"], []))
            from mac.roles_service import machine_hardware_satisfies

            hardware_ok, _reasons = machine_hardware_satisfies(
                json_loads(bound_role["hardware_requirements"], {}),
                machine.hardware,
            )
            if not hardware_ok:
                return "role_hardware_insufficient"
            if not agent.persona_instance_id:
                return "role_not_accepted_by_soul"
            conn.execute(
                "UPDATE persona_instances SET updated_at = updated_at WHERE id = ?",
                (agent.persona_instance_id,),
            )
            instance = conn.execute(
                "SELECT persona_id FROM persona_instances WHERE id = ?",
                (agent.persona_instance_id,),
            ).fetchone()
            if instance is None or not instance["persona_id"]:
                return "role_not_accepted_by_soul"
            persona_id = str(instance["persona_id"])
            conn.execute(
                "UPDATE personas SET updated_at = updated_at WHERE id = ?",
                (persona_id,),
            )
            persona = conn.execute(
                "SELECT name, metadata FROM personas WHERE id = ?",
                (persona_id,),
            ).fetchone()
            if persona is None:
                return "role_not_accepted_by_soul"
            persona_metadata = json_loads(persona["metadata"], {})
            explicit_slugs = persona_metadata.get("role_slugs")
            if isinstance(explicit_slugs, list) and explicit_slugs:
                allowed_slugs = {
                    str(value).strip().lower() for value in explicit_slugs if str(value).strip()
                }
            else:
                default_slug = (
                    str(persona["name"] or "").strip().lower().replace(" ", "-").replace("_", "-")
                )
                allowed_slugs = {default_slug} if default_slug else set()
            if str(bound_role["slug"]) not in allowed_slugs:
                return "role_not_accepted_by_soul"

        required_caps = set(task.required_capabilities) | role_required_caps
        if not required_caps.issubset(set(agent.capabilities)):
            return "capabilities_missing"
        return None

    def _agent_availability_for_task(
        self, agent: Agent, task: Task, *, allow_cooperative_reuse: bool = False
    ) -> Tuple[bool, str]:
        task_authorization = self._active_break_glass_authorization(task.id)
        break_glass = (
            task_authorization
            if task_authorization is not None and task_authorization.agent_id == agent.id
            else None
        )
        if task_authorization is not None and break_glass is None:
            return False, "break_glass_agent_mismatch"
        if agent.dispatch_hold and break_glass is None:
            return False, "agent_dispatch_held"
        if agent.status not in {AgentStatus.IDLE.value, AgentStatus.BUSY.value}:
            return False, "agent_status_unavailable"
        if not self._advisory_health_dispatch_ready(agent):
            return False, "agent_health_unavailable"
        if not self.directives.agent_policy_ready(agent.id):
            return False, "directive_policy_unacknowledged"
        try:
            self._assert_current_read_only_report_task_contract(task)
        except ValidationError:
            return False, "report_repository_contract_invalid"
        if metadata_declares_read_only_report_repository(
            task.metadata
        ) and not agent_has_read_only_report_repository_executor(agent.resources):
            return False, "report_repository_executor_missing"
        # Hard safety exclusion used by crash-repair tasks: a worker must not
        # diagnose or approve a crash in the same revision that killed it.
        # Unlike cooperative distinctness this is not relaxed when the pool is
        # exhausted; the repair waits for an unaffected healthy peer.
        task_metadata = ensure_json_object(task.metadata)
        explicit_excluded: set[str] = set()
        for key in ("excluded_agent_ids", "retry_excluded_agent_ids"):
            values = task_metadata.get(key)
            if isinstance(values, list):
                explicit_excluded.update(str(value) for value in values if str(value))
        if agent.id in explicit_excluded:
            return False, "explicit_agent_excluded"
        # Distinct-executor separation is a *preference*, not a hard rule: when
        # the whole pool has already participated in the family, the dispatcher
        # relaxes it (allow_cooperative_reuse=True) rather than leaving the task
        # permanently undispatchable.  This mirrors the reviewer-independence
        # fallback the review path already has.
        if not allow_cooperative_reuse and agent.id in self._coordination_excluded_agent_ids(task):
            return False, "cooperative_distinct_agent_excluded"
        target_agent_id = (
            task.metadata.get("target_agent_id") if isinstance(task.metadata, dict) else None
        )
        if target_agent_id and agent.id != str(target_agent_id):
            return False, "target_agent_id_mismatch"
        target_agent_name = (
            task.metadata.get("target_agent_name") if isinstance(task.metadata, dict) else None
        )
        if target_agent_name and agent.name != str(target_agent_name):
            return False, "target_agent_name_mismatch"
        required_runtime_digest = self._task_required_runtime_digest(task)
        if required_runtime_digest and agent.running_digest != required_runtime_digest:
            return False, "runtime_digest_mismatch"
        try:
            machine = self.get_machine(agent.machine_id)
        except NotFoundError:
            return False, "agent_machine_missing"
        if not machine.trusted:
            return False, "machine_untrusted"
        if self._agent_active_lease_count(agent.id) >= self._agent_capacity(agent):
            return False, "agent_capacity_full"
        if not self._machine_allows_tenant(machine, self._task_tenant_id(task)):
            return False, "machine_tenant_not_allowed"
        if break_glass is not None:
            # The operator selected this exact trusted host because ordinary
            # compatibility may itself be what needs repair: stale runtime
            # digests, missing sandbox-visible commands, broken coding-route
            # proofs, capabilities, roles, or task target hints.  Retain the
            # hard trust, health, status, capacity, and tenant boundaries above,
            # then bypass those task/agent compatibility checks only for this
            # short-lived authorization.
            return True, "break_glass_authorized"
        if not self._agent_resources_satisfy(agent, machine, task):
            return False, "agent_resources_insufficient"
        if not self._agent_has_clean_managed_repository_source(agent, task):
            return False, "repository_source_dirty"
        if not self._agent_has_repository_commands(agent, task):
            return False, "repository_commands_missing"
        coding_route_ok, coding_route_reason = self._agent_has_verified_coding_route(agent, task)
        if not coding_route_ok:
            return False, coding_route_reason
        # Role + hardware gates. Both no-op when neither the agent nor the
        # task carry role/hardware metadata, so the legacy capability path
        # below stays the dominant matcher for un-roled fleets.
        required_role = (
            task.metadata.get("required_role") if isinstance(task.metadata, dict) else None
        )
        if required_role:
            # Look up the target role first. An unknown role can never be
            # served, regardless of whether the agent is role-bound or a
            # multi-role dispatcher — fail closed.
            try:
                target_role = self.roles.get_role(str(required_role))
            except NotFoundError:
                return False, "required_role_unknown"
            if agent.role_id is not None:
                # Role-bound agent: keep the strict slug match so a tenant
                # using role-specific agents still gets the original
                # routing guarantee.
                try:
                    bound_role = self.roles.get_role(agent.role_id)
                except NotFoundError:
                    return False, "agent_role_unknown"
                if bound_role.slug != required_role:
                    return False, "required_role_mismatch"
            else:
                # Dispatcher case (job-per-task roles spec §6.1 Option B):
                # the runner agent has no role_id but carries the union of
                # role capabilities and re-attributes the work to a
                # role-specific identity at Job-launch time. Allow the
                # claim iff the dispatcher's capabilities cover the
                # target role's required_capabilities. The task-level
                # capabilities are still enforced by the union check at
                # the end of this method.
                if not set(target_role.required_capabilities).issubset(set(agent.capabilities)):
                    return False, "required_role_capabilities_missing"
        role_required_caps: set = set()
        if agent.role_id is not None:
            try:
                role = self.roles.get_role(agent.role_id)
            except NotFoundError:
                role = None
            if role is not None:
                ok, _reasons = self.roles.validate_hardware(role, machine)
                if not ok:
                    return False, "role_hardware_insufficient"
                # Soul-role compatibility is re-checked at dispatch time
                # rather than only at assignment time, so a persona edit
                # that narrows the allowed role list immediately stops
                # affected agents from being eligible.
                if not self.roles.soul_accepts_role(agent, role):
                    return False, "role_not_accepted_by_soul"
                role_required_caps = set(role.required_capabilities)
        capabilities = set(agent.capabilities)
        required = set(task.required_capabilities) | role_required_caps
        if not required.issubset(capabilities):
            return False, "capabilities_missing"
        return True, "matched"

    def _record_routing_skip(
        self,
        *,
        name: str,
        agent_id: Optional[str],
        task: Task,
        reason: str,
        route: str,
        candidate_rank: int,
        reason_class: str,
        dry_run: bool = False,
    ) -> None:
        self.record_log(
            name,
            level="debug",
            layer="control_plane",
            source=agent_id or route,
            subject_type="task",
            subject_id=task.id,
            detail={
                "agent_id": agent_id,
                "task_id": task.id,
                "reason": reason,
                "reason_class": reason_class,
                "route": route,
                "candidate_rank": candidate_rank,
                "dry_run": dry_run,
            },
        )

    def _agent_has_repository_commands(self, agent: Agent, task: Task) -> bool:
        metadata = ensure_json_object(task.metadata)
        required_commands = (
            _repository_host_required_commands_from_metadata(metadata)
            if _agent_requires_openshell(agent)
            else _repository_required_commands_from_metadata(metadata)
        )
        if not required_commands:
            return True
        available = _agent_resource_command_names(ensure_json_object(agent.resources))
        return set(required_commands).issubset(available)

    def _agent_has_clean_managed_repository_source(self, agent: Agent, task: Task) -> bool:
        """Reject work targeting the dirty managed source reported by a worker.

        Workers already refuse to prepare a repository worktree from a dirty
        managed source checkout.  Projecting that same fact into dispatch keeps
        ready-task and why-unclaimed results authoritative instead of assigning
        work that is guaranteed to fail during repository preparation.  The
        report describes the worker runtime's own managed repository, though,
        so it must not block a task targeting a different repository.

        Absence of a current source-state report is not treated as dirty: some
        workers clone task repositories remotely and do not manage a local
        source base.  Other readiness/credential gates remain responsible for
        requiring source-state attestations where their execution mode needs
        one.
        """
        if not self._task_is_repo_coupled(task):
            return True
        resources = ensure_json_object(agent.resources)
        source_state = ensure_json_object(resources.get("source_state"))
        if source_state.get("schema") != "mac.worker_source_state.v1":
            return True
        source_names: set[str] = set()

        def add_name(value: Any, *, path: bool = False) -> None:
            raw = str(value or "").strip()
            if not raw:
                return
            name = Path(raw).name if path else raw
            normalized = name.removesuffix(".git").strip().lower()
            if normalized:
                source_names.add(normalized)

        add_name(source_state.get("repository_name"))
        add_name(source_state.get("repo_path"), path=True)
        if not source_names:
            return True

        metadata = ensure_json_object(task.metadata)
        execution = ensure_json_object(metadata.get("execution_contract"))
        origin = ensure_json_object(metadata.get("origin"))
        contract = ensure_json_object(execution.get("repository_contract"))
        if not contract:
            contract = ensure_json_object(origin.get("repository_contract"))
        target_names: set[str] = set()

        def add_target(value: Any, *, path: bool = False) -> None:
            raw = str(value or "").strip()
            if not raw:
                return
            name = Path(raw).name if path else raw
            normalized = name.removesuffix(".git").strip().lower()
            if normalized:
                target_names.add(normalized)

        add_target(execution.get("repository_path"), path=True)
        add_target(origin.get("repository_path"), path=True)
        add_target(origin.get("repository_name"))
        add_target(contract.get("project"))
        add_target(task.project)
        if source_names.isdisjoint(target_names):
            return True
        return source_state.get("dirty") is not True

    def _coding_route_proof(self, agent: Agent) -> "CodingRouteProof":
        """Summarize an agent's reported coding routes for :mod:`mac.coding_route_gate`."""
        from mac.coding_route_gate import proof_from_resources

        return proof_from_resources(
            ensure_json_object(agent.resources),
            requires_openshell=_agent_requires_openshell(agent),
            listed_agents=self.coding_policy()["agents"],
        )

    def _agent_has_verified_coding_route(self, agent: Agent, task: Task) -> Tuple[bool, str]:
        """Require a fresh, exact in-sandbox route proof before repo dispatch.

        A thin reading of :mod:`mac.coding_route_gate`, which the allocator
        asks too, so the claim boundary and every allocation path agree.
        """
        from mac.coding_route_gate import refusal, strict_enabled

        if not self._task_is_repo_coupled(task) or not _agent_requires_openshell(agent):
            return True, "not_required"
        if not strict_enabled():
            return True, "strict_route_verification_disabled"
        reason = refusal(
            self._coding_route_proof(agent),
            task_requires_coding=True,
            pinned_model=self._task_pinned_coding_model(task),
        )
        return (False, reason) if reason else (True, "verified")

    @staticmethod
    def _task_pinned_coding_model(task: Task) -> str:
        metadata = ensure_json_object(task.metadata)
        is_review = isinstance(metadata.get("review_context"), dict)
        key = "review_model" if is_review else "model"
        value = str(metadata.get(key) or "").strip()
        if value:
            return value[:256]
        runtime = ensure_json_object(metadata.get("runtime"))
        return str(runtime.get(key) or "").strip()[:256]

    def _task_required_runtime_digest(self, task: Task) -> Optional[str]:
        metadata = ensure_json_object(task.metadata)
        runtime = metadata.get("runtime")
        runtime_meta = ensure_json_object(runtime) if isinstance(runtime, dict) else {}
        for value in (
            runtime_meta.get("required_runtime_digest"),
            runtime_meta.get("runtime_digest"),
            runtime_meta.get("base_runtime_digest"),
            metadata.get("required_runtime_digest"),
            metadata.get("runtime_digest"),
        ):
            text = str(value or "").strip()
            if text:
                return text
        runtime_id = str(
            runtime_meta.get("runtime_environment_id")
            or runtime_meta.get("required_runtime_environment_id")
            or metadata.get("runtime_environment_id")
            or metadata.get("required_runtime_environment_id")
            or ""
        ).strip()
        if not runtime_id:
            return None
        try:
            return self.get_runtime(runtime_id).digest
        except NotFoundError:
            return "__unknown_runtime_digest__"

    def _default_review_policy(self, task: Task) -> JsonDict:
        metadata = ensure_json_object(task.metadata)
        for key in ("review", "default_review"):
            value = metadata.get(key)
            if isinstance(value, dict):
                return ensure_json_object(value)
        return {}

    def _default_review_required_capabilities(
        self,
        task: Task,
        policy: Optional[JsonDict] = None,
    ) -> List[str]:
        policy = ensure_json_object(policy or self._default_review_policy(task))
        required = set(_metadata_string_list(policy.get("required_capabilities")))
        if (
            policy.get("inherit_task_capabilities") is True
            or policy.get("inherit_required_capabilities") is True
        ):
            required.update(str(capability) for capability in task.required_capabilities)
        return sorted(required)

    def _default_review_disabled(self, task: Task) -> bool:
        policy = self._default_review_policy(task)
        mode = str(policy.get("mode") or policy.get("workflow") or "").strip().lower()
        return (
            mode == "manual"
            or policy.get("manual") is True
            or policy.get("auto") is False
            or policy.get("enabled") is False
        )

    def _default_review_evidence(self, task: Task) -> Tuple[Optional[Evidence], JsonDict]:
        evidence = self.list_evidence(task.id)
        if not evidence:
            return None, {"reason": "no_evidence"}
        successful = [item for item in evidence if self._evidence_returncode(item) == 0]
        if not successful:
            return None, {"reason": "no_successful_evidence"}
        rejected: List[JsonDict] = []
        for item in reversed(successful):
            assessment = self._assess_default_review_evidence(task, item)
            if assessment["valid"]:
                return item, assessment
            rejected.append(
                {
                    "evidence_id": item.id,
                    "reason": assessment["reason"],
                    "problems": assessment.get("problems", []),
                }
            )
        return None, {
            "reason": "evidence_not_verifiable",
            "rejected_evidence": rejected[:5],
        }

    def _bound_review_evidence(self, task: Task) -> Tuple[Optional[Evidence], JsonDict]:
        """Resolve the immutable executor evidence target for this review attempt."""
        metadata = ensure_json_object(task.metadata)
        target = ensure_json_object(metadata.get("review_target"))
        target_id = str(target.get("executor_evidence_id") or "").strip()
        if target_id:
            try:
                evidence = self.get_evidence(target_id)
            except NotFoundError:
                return None, {
                    "reason": "review_target_missing",
                    "executor_evidence_id": target_id,
                }
            assessment = self._assess_default_review_evidence(task, evidence)
            if assessment.get("valid"):
                return evidence, assessment
            return None, {
                "reason": "bound_evidence_not_verifiable",
                "executor_evidence_id": target_id,
                "problems": assessment.get("problems", []),
            }

        # Rolling-upgrade compatibility for tasks that entered NEEDS_REVIEW
        # before review_target existed. Bind once, then never follow newer rows.
        evidence, assessment = self._default_review_evidence(task)
        if evidence is not None:
            metadata["review_target"] = {
                "executor_evidence_id": evidence.id,
                "attempt_count": task.attempt_count,
                "recorded_at": utcnow(),
            }
            self.store.execute(
                "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
                (json_dumps(metadata), utcnow(), task.id),
            )
        return evidence, assessment

    def _assess_default_review_evidence(self, task: Task, evidence: Evidence) -> JsonDict:
        if self._evidence_returncode(evidence) != 0:
            return {
                "valid": False,
                "reason": "executor_not_successful",
                "problems": ["evidence returncode is not zero"],
            }
        manifest = evidence.metadata.get("verification") or evidence.metadata.get("mac_evidence")
        if not isinstance(manifest, dict):
            return {
                "valid": False,
                "reason": "missing_verification_manifest",
                "problems": ["evidence metadata lacks verification manifest"],
            }
        problems: List[str] = []
        schema = str(manifest.get("schema") or "").strip()
        if schema != VERIFICATION_SCHEMA:
            problems.append("verification.schema must be %s" % VERIFICATION_SCHEMA)
        # Canonical names only (mac-q38). Aliases were a maintainability
        # multiplier — every alias is a separate door downstream
        # validation must remember. Status must be ``complete``; the
        # alternative aliases (verified/pass/passed) are rejected at the
        # boundary. Same for evidence_type below.
        status = str(manifest.get("status") or "").strip().lower()
        if status != "complete":
            problems.append('verification.status must be "complete"')
        evidence_type = str(manifest.get("evidence_type") or "").strip().lower()
        if not evidence_type:
            problems.append("verification.evidence_type is required")
        if problems:
            return {
                "valid": False,
                "reason": "invalid_verification_manifest",
                "evidence_type": evidence_type or None,
                "problems": problems,
            }
        if evidence_type == "review_verdict":
            return {
                "valid": False,
                "reason": "review_verdict_is_not_executor_evidence",
                "evidence_type": evidence_type,
                "problems": ["review_verdict evidence only satisfies the reviewer verdict gate"],
            }
        # Root of trust (mac-ng2). The verification manifest must carry
        # ``signed_by`` (an agent_id) and ``signature`` (HMAC v1) made
        # with that agent's attestation key. Without this any executor
        # could self-approve by writing valid-looking JSON. Verification
        # is per-agent: the signer's key must be on file in the
        # ``agents.attestation_key_ciphertext`` column.
        signed_by = str(manifest.get("signed_by") or "").strip()
        signature = str(manifest.get("signature") or "").strip()
        if not signed_by or not signature:
            return {
                "valid": False,
                "reason": "manifest_not_signed",
                "evidence_type": evidence_type,
                "problems": ["verification.signed_by and verification.signature are required"],
            }
        signer_key = self._agent_attestation_key(signed_by)
        if signer_key is None:
            return {
                "valid": False,
                "reason": "signer_unknown",
                "evidence_type": evidence_type,
                "problems": [
                    "verification.signed_by does not match a known agent with an attestation key"
                ],
            }
        if not verify_verification_manifest_signature(signer_key, manifest, signature):
            # Key-rotation tolerance (mac-s2vz, extended): if the signer was
            # re-keyed AFTER this evidence was signed (e.g. a gateway redeploy
            # rotated the executor's key mid-review — the exact 2026-07-14
            # incident), verify against the retained previous key. Without this
            # the ALREADY-BOUND review_target evidence is rejected every sweep
            # tick and the task parks in waiting_for_verifiable_evidence forever.
            # Mirrors the fallback already in _find_review_verdict_evidence.
            rotated_ok = False
            rotation_row = self.store.query_one(
                "SELECT attestation_key_rotated_at FROM agents WHERE id = ?",
                (signed_by,),
            )
            rotated_at = rotation_row["attestation_key_rotated_at"] if rotation_row else None
            if rotated_at and getattr(evidence, "created_at", None):
                try:
                    predates = parse_time(rotated_at) > parse_time(evidence.created_at)
                except ValueError:
                    predates = False
                if predates:
                    rotated_ok = self._verify_manifest_against_retained_keys(
                        signed_by, manifest, signature
                    )
            if not rotated_ok:
                return {
                    "valid": False,
                    "reason": "signature_invalid",
                    "evidence_type": evidence_type,
                    "problems": [
                        "verification.signature does not verify against signed_by's attestation key"
                    ],
                }
        if self._read_only_report_tests_deferred(task, evidence):
            # A deferred contract test was a request for hub-side
            # verification, which no longer exists. Nothing else will ever
            # run that test, so the report cannot be approved.
            return {
                "valid": False,
                "reason": "report_contract_test_deferred",
                "evidence_type": evidence_type,
                "problems": [
                    "read-only report deferred its contract test; reports must carry "
                    "a verifier-run Linux contract test result"
                ],
            }
        type_problems = self._verification_type_problems(task, manifest, evidence_type)
        if type_problems:
            return {
                "valid": False,
                "reason": "verification_contract_failed",
                "evidence_type": evidence_type,
                "problems": type_problems,
            }
        return {
            "valid": True,
            "reason": "verification_contract_satisfied",
            "evidence_type": evidence_type,
            "signed_by": signed_by,
            "verified_by": "default-review-evidence-v1",
        }

    def _verification_type_problems(
        self,
        task: Task,
        manifest: JsonDict,
        evidence_type: str,
    ) -> List[str]:
        declared_outcome = declared_non_repository_outcome_evidence_type(task.metadata)
        if evidence_type == "investigation" and declared_outcome != "investigation":
            return [
                "investigation evidence requires an operator-authored "
                "investigation execution contract"
            ]
        if declared_outcome and evidence_type != declared_outcome:
            # Mirror of the coercion the worker already applies to its own
            # pre-submit checks (worker.py, "Coerce rather than reject").
            # The worker corrects the type locally but still SUBMITS the
            # manifest its executor wrote, so the hub re-validated a
            # repo-coupled claim at face value and the two halves disagreed.
            #
            # Observed live 2026-09-25 on the kit onboarding task: the task
            # declares evidence_type=investigation with
            # repository_required=False and instructs "do NOT push or open a
            # pull request", the executor defaulted to repo_change because it
            # made a local commit, and RepoChangeValidator then demanded
            # pushed=true/pr_url -- exactly what the task forbade. The agent
            # did the work correctly and was refused by the gate for obeying
            # its instructions; three attempts burned on an unsatisfiable
            # contract.
            #
            # The task's declared contract is the operator's authoritative
            # intent. An agent cannot unilaterally impose a stricter
            # requirement than the one it was given, so decode the evidence
            # with the declared type rather than the claimed one.
            evidence_type = declared_outcome
        problems = validate_evidence_type(
            evidence_type,
            manifest,
            passed_check_count=self._passed_verification_check_count,
            allow_empty_repo_change=self._allows_empty_repo_change_evidence(task, evidence_type),
            repo_coupled=self._task_is_repo_coupled(task),
            require_tests=self._task_requires_tests(task),
            require_verifier_tests=bool(_repository_contract_test_command_for_task(task)),
            expected_reconcile_head_sha=expected_head_sha_from_task(
                {"id": task.id, "metadata": task.metadata}
            ),
        )
        problems.extend(self._required_changed_file_problems(task, manifest))
        return problems

    def _required_changed_file_problems(self, task: Task, manifest: JsonDict) -> List[str]:
        required = _required_changed_files_from_metadata(ensure_json_object(task.metadata))
        if not required:
            return []
        repo = manifest.get("repo") if isinstance(manifest.get("repo"), dict) else {}
        changed = _metadata_path_list(repo.get("files_changed")) if isinstance(repo, dict) else []
        missing = [
            path
            for path in required
            if not any(_repo_path_satisfies_requirement(item, path) for item in changed)
        ]
        if not missing:
            return []
        return ["repo evidence missing required changed files: %s" % ", ".join(missing)]

    def _allows_empty_repo_change_evidence(self, task: Task, evidence_type: str) -> bool:
        if str(evidence_type or "").strip().lower() != "repo_change":
            return False
        metadata = ensure_json_object(task.metadata)
        origin = ensure_json_object(metadata.get("origin"))
        remediation = ensure_json_object(metadata.get("remediation"))
        return (
            origin.get("type") == "beads_source_remediation"
            or remediation.get("type") == "beads_source_refresh"
        )

    def _task_is_repo_coupled(self, task: Task) -> bool:
        """mem-11: True when the task carries a repository_contract — a code task
        expected to produce a pushed repo change. ``operator_result`` evidence is
        rejected for such tasks (the verified task_d7c51a0b jam was a code task
        that emitted a free-text operator_result with no commit/push)."""
        metadata = ensure_json_object(task.metadata)
        # An explicitly declared report/answer task is non-code; operator_result
        # is its correct evidence type, so it is not repo-coupled here.
        if metadata_declares_report_deliverable(metadata):
            return False
        for path in (
            ("execution_contract", "repository_contract"),
            ("origin", "repository_contract"),
            ("repository_contract",),
        ):
            contract = _nested_json_object(metadata, *path)
            if isinstance(contract, dict) and contract:
                return True
        return False

    def _task_requires_tests(self, task: Task) -> bool:
        """mac-wjy3: True when the task's repository_contract explicitly lists
        ``tests`` in its required evidence. Conservative — config/remediation
        tasks (which don't opt in) are unaffected; only contracts that demand
        tests reject a tests:null manifest."""
        metadata = ensure_json_object(task.metadata)
        for path in (
            ("execution_contract", "repository_contract"),
            ("origin", "repository_contract"),
            ("repository_contract",),
        ):
            contract = _nested_json_object(metadata, *path)
            if not isinstance(contract, dict) or not contract:
                continue
            evidence = ensure_json_object(contract.get("evidence"))
            required = (
                evidence.get("required") if isinstance(evidence.get("required"), list) else []
            )
            if any(str(r).strip().lower() in {"tests", "test"} for r in required):
                return True
        return False

    def _require_pushed_repo_anchor(self, manifest: JsonDict) -> List[str]:
        # Canonical field names only (mac-q38). The previous code
        # accepted ``git``/``commit``/``commit_sha``/``changed_files``/
        # ``pushed_ref``/``pull_request_url``/etc. — each alias is a
        # separate doorway. Single canonical schema:
        #   verification.repo: { head_sha, files_changed, dirty, pushed,
        #                        remote_ref, pr_url? }
        repo = manifest.get("repo")
        if not isinstance(repo, dict):
            return ["repo evidence requires verification.repo object"]
        problems: List[str] = []
        head_sha = str(repo.get("head_sha") or "").strip()
        if not _GIT_SHA_RE.match(head_sha):
            problems.append("repo.head_sha must be a git SHA")
        dirty = repo.get("dirty")
        if dirty not in {False, "false", "False", 0, "0"}:
            problems.append("repo evidence must declare dirty=false")
        pushed = repo.get("pushed") is True or str(repo.get("pushed") or "").lower() == "true"
        remote_ref = str(repo.get("remote_ref") or "").strip()
        pr_url = str(repo.get("pr_url") or "").strip()
        if not (pushed and remote_ref) and not pr_url:
            problems.append("repo evidence requires pushed=true with remote_ref, or pr_url")
        return problems

    def _passed_verification_check_count(self, manifest: JsonDict) -> int:
        # Canonical names only (mac-q38): ``tests`` and ``checks``.
        # ``test_runs`` was an alias; rejecting it here.
        count = 0
        for item in self._verification_item_candidates(manifest.get("tests")):
            if self._verification_item_passed(item):
                count += 1
        for item in self._verification_item_candidates(manifest.get("checks")):
            if self._verification_item_passed(item):
                count += 1
        return count

    def _verification_item_candidates(self, value: Any) -> List[Any]:
        if value is None:
            return []
        if isinstance(value, list):
            return value
        if isinstance(value, dict):
            return [value]
        return []

    def _verification_item_passed(self, item: Any) -> bool:
        # Keep repo fields canonical, but accept common structured pass/fail
        # spellings for test/check result objects. Agents and tools naturally
        # emit "result=passed", booleans, and nested smoke/full-suite records;
        # rejecting those equivalent facts caused good pushed work to dead-letter.
        if isinstance(item, list):
            return any(self._verification_item_passed(nested) for nested in item)
        if not isinstance(item, dict):
            return False
        if item.get("skipped") is True or str(item.get("status") or "").strip().lower() in {
            "skipped",
            "deferred",
        }:
            # Nothing ran: whatever else the item says, it is not a pass.
            return False
        if "returncode" in item:
            return self._verification_int_value(item["returncode"]) == 0
        failed = self._verification_int_value(item.get("failed"))
        if failed is not None and failed > 0:
            return False
        if str(item.get("status") or "").strip().lower() in {
            "pass",
            "passed",
            "success",
            "successful",
            "succeeded",
            "ok",
        }:
            return True
        if str(item.get("result") or "").strip().lower() in {
            "pass",
            "passed",
            "success",
            "successful",
            "succeeded",
            "ok",
        }:
            return True
        if str(item.get("outcome") or "").strip().lower() in {
            "pass",
            "passed",
            "success",
            "successful",
            "succeeded",
            "ok",
        }:
            return True
        for key in ("passed", "success", "succeeded", "ok", "satisfied"):
            value = item.get(key)
            if value is True:
                return True
            number = self._verification_int_value(value)
            if number is not None and number > 0 and failed == 0:
                return True
        bool_values = [value for value in item.values() if isinstance(value, bool)]
        if bool_values and len(bool_values) == len(item) and all(bool_values):
            return True
        return any(
            self._verification_item_passed(nested)
            for nested in item.values()
            if isinstance(nested, (dict, list))
        )

    def _verification_int_value(self, value: Any) -> Optional[int]:
        try:
            if isinstance(value, bool):
                return int(value)
            return int(value)
        except (TypeError, ValueError):
            return None

    def _evidence_returncode(self, evidence: Evidence) -> Optional[int]:
        value = evidence.metadata.get("returncode")
        if value is None:
            return None
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    @staticmethod
    def _read_only_report_tests_deferred(task: Task, evidence: Evidence) -> bool:
        if not metadata_declares_read_only_report_repository(task.metadata):
            return False
        manifest = ensure_json_object(evidence.metadata.get("verification"))
        tests = manifest.get("tests")
        return isinstance(tests, list) and any(
            isinstance(item, dict)
            and (
                item.get("status") == "deferred"
                or item.get("execution_environment") == "hub_verify_pending"
            )
            for item in tests
        )

    def _find_review_verdict_evidence(
        self,
        task_id: str,
        reviewer_agent_id: str,
        *,
        executor_evidence_id: str,
        verdict_evidence_id: Optional[str] = None,
        not_before: Optional[str] = None,
    ) -> Tuple[Optional[Evidence], List[str]]:
        """Locate the reviewer's signed verdict evidence row, or return
        ``(None, problems)`` if it doesn't exist yet (mac-jqb v1).

        The verdict is a separate Evidence row authored by the reviewer
        (not the executor) with a signed verification manifest of type
        ``review_verdict`` that names the executor's evidence_id.
        Without this row the workflow blocks — it will no longer
        auto-approve in the same process that selected the reviewer.

        Shape required for a valid verdict:
            evidence.metadata.returncode == 0
            evidence.metadata.verification:
                schema = mac.worker_evidence.v1
                status = complete
                evidence_type = review_verdict
                verdict in {approved, rejected}
                reviewed_evidence_id == executor_evidence_id
                signed_by = <reviewer_agent_id>
                signature = <HMAC of manifest under reviewer's key>
        """
        problems: List[str] = []
        reviewed_task = self.get_task(task_id)
        for evidence in reversed(self.list_evidence(task_id)):
            if verdict_evidence_id is not None and evidence.id != verdict_evidence_id:
                continue
            if evidence.created_by != reviewer_agent_id:
                continue
            if not_before is not None:
                try:
                    if parse_time(evidence.created_at) < parse_time(not_before):
                        problems.append("verdict %s predates review request" % evidence.id)
                        continue
                except ValueError:
                    problems.append("verdict %s has invalid created_at" % evidence.id)
                    continue
            if self._evidence_returncode(evidence) != 0:
                problems.append("verdict evidence %s has nonzero returncode" % evidence.id)
                continue
            manifest = evidence.metadata.get("verification")
            if not isinstance(manifest, dict):
                problems.append("verdict evidence %s missing verification manifest" % evidence.id)
                continue
            if str(manifest.get("evidence_type") or "").strip().lower() != "review_verdict":
                continue  # not a verdict evidence row, skip silently
            if str(manifest.get("schema") or "").strip() != VERIFICATION_SCHEMA:
                problems.append("verdict %s schema mismatch" % evidence.id)
                continue
            if str(manifest.get("status") or "").strip().lower() != "complete":
                problems.append("verdict %s status not complete" % evidence.id)
                continue
            reviewed = str(manifest.get("reviewed_evidence_id") or "").strip()
            if reviewed != executor_evidence_id:
                problems.append(
                    "verdict %s references wrong executor evidence: %s != %s"
                    % (evidence.id, reviewed, executor_evidence_id)
                )
                continue
            signed_by = str(manifest.get("signed_by") or "").strip()
            signature = str(manifest.get("signature") or "").strip()
            if signed_by != reviewer_agent_id:
                problems.append("verdict %s signed_by != reviewer" % evidence.id)
                continue
            key = self._agent_attestation_key(signed_by)
            if key is None:
                problems.append("verdict %s signer has no attestation key" % evidence.id)
                continue
            if not verify_verification_manifest_signature(key, manifest, signature):
                # The signature does not verify against the signer's CURRENT
                # key. Before failing, check whether the key was rotated AFTER
                # this evidence was signed; if so, verify against the retained
                # previous key (the key active at signing time). A routine
                # re-key (e.g. an agent re-keyed after a redeploy) must not
                # invalidate a verdict that was validly signed beforehand
                # (mac-s2vz followup).
                rotation_row = self.store.query_one(
                    "SELECT attestation_key_rotated_at FROM agents WHERE id = ?",
                    (signed_by,),
                )
                rotated_at = rotation_row["attestation_key_rotated_at"] if rotation_row else None
                predates_rotation = False
                if rotated_at and evidence.created_at:
                    try:
                        predates_rotation = parse_time(rotated_at) > parse_time(evidence.created_at)
                    except ValueError:
                        predates_rotation = False
                prev_ok = False
                if predates_rotation:
                    prev_ok = self._verify_manifest_against_retained_keys(
                        signed_by, manifest, signature
                    )
                if not prev_ok:
                    if predates_rotation:
                        # Rotated, and the retained previous key is absent
                        # (rotation predates key retention) or also fails:
                        # surface the clear key-rotation error + guidance.
                        problems.append(
                            "verdict %s signed under rotated attestation key "
                            "(rotated_at=%s, evidence created_at=%s); "
                            "the reviewer must re-sign with the current key"
                            % (evidence.id, rotated_at, evidence.created_at)
                        )
                    else:
                        problems.append("verdict %s signature does not verify" % evidence.id)
                    continue
                # prev_ok: the signature verifies against the key that was
                # active at signing time — accept and fall through to the
                # remaining verdict checks below.
            executor_evidence = self.get_evidence(executor_evidence_id)
            executor_manifest = executor_evidence.metadata.get("verification") or {}
            if not isinstance(executor_manifest, dict):
                problems.append(
                    "verdict %s cannot resolve executor verification manifest" % evidence.id
                )
                continue
            if str(manifest.get("verdict") or "").strip().lower() == "approved":
                replayed_acceptance = evaluate_acceptance(
                    reviewed_task.metadata,
                    executor_manifest,
                )
                if replayed_acceptance.get("required"):
                    semantic_problems = acceptance_result_problems(
                        replayed_acceptance,
                        manifest.get("acceptance"),
                    )
                    if semantic_problems:
                        problems.extend(
                            "verdict %s %s" % (evidence.id, problem)
                            for problem in semantic_problems
                        )
                        continue
                    review_status = manifest.get("review_status")
                    if (
                        not isinstance(review_status, dict)
                        or review_status.get("structural") != "pass"
                        or review_status.get("semantic") != "pass"
                    ):
                        problems.append(
                            "verdict %s must expose passing structural and semantic review status"
                            % evidence.id
                        )
                        continue
            verdict = str(manifest.get("verdict") or "").strip().lower()
            if verdict not in {"approved", "rejected"}:
                problems.append("verdict %s requires verdict approved or rejected" % evidence.id)
                continue
            digest = str(manifest.get("worktree_digest") or "").strip()
            if not re.match(r"^sha256:[0-9a-f]{64}$", digest):
                problems.append("verdict %s requires worktree_digest sha256" % evidence.id)
                continue
            llm_problems = cross_llm_review_problems(
                executor_manifest,
                manifest,
                requirements=review_diversity_requirements(reviewed_task),
            )
            if llm_problems:
                problems.extend(
                    "verdict %s %s" % (evidence.id, problem) for problem in llm_problems
                )
                continue
            # Deterministic finalization can produce a signed, fail-closed
            # rejection even when the reviewer agent never emitted a semantic
            # verdict. That is useful evidence of a harness/protocol failure,
            # but it is not a code-review decision and must never consume an
            # executor attempt as though a reviewer rejected the patch.
            if "semantic_verdict" in manifest:
                semantic_verdict = str(manifest.get("semantic_verdict") or "").strip().lower()
                if semantic_verdict not in {"approved", "rejected"}:
                    problems.append("verdict %s semantic verdict is invalid" % evidence.id)
                    continue
            if verdict == "rejected":
                feedback_problems = rejected_verdict_feedback_problems(manifest)
                if feedback_problems:
                    problems.extend(
                        "verdict %s %s" % (evidence.id, problem) for problem in feedback_problems
                    )
                    continue
                return evidence, []
            executor_repo = executor_manifest.get("repo")
            if isinstance(executor_repo, dict):
                repo_problems = self._require_pushed_repo_anchor(manifest)
                if repo_problems:
                    problems.extend(
                        "verdict %s %s" % (evidence.id, problem) for problem in repo_problems
                    )
                    continue
                review_repo = manifest.get("repo") if isinstance(manifest.get("repo"), dict) else {}
                executor_changed = _metadata_path_list(executor_repo.get("files_changed"))
                review_changed = _metadata_path_list(review_repo.get("files_changed"))
                if executor_changed and set(review_changed) != set(executor_changed):
                    problems.append(
                        "verdict %s repo.files_changed does not match executor evidence: %s != %s"
                        % (evidence.id, review_changed, executor_changed)
                    )
                    continue
                reviewed_sha = str((manifest.get("repo") or {}).get("head_sha") or "").strip()
                executor_sha = str(executor_repo.get("head_sha") or "").strip()
                if reviewed_sha != executor_sha:
                    problems.append(
                        "verdict %s repo.head_sha does not match executor evidence: %s != %s"
                        % (evidence.id, reviewed_sha, executor_sha)
                    )
                    continue
                # mac-9kij: when the executor's evidence carries a local
                # repo path, recompute ``git rev-parse <head_sha>^{commit}``
                # to confirm the SHA actually exists in that repo. This
                # catches the "reviewer typed back what executor typed,
                # but neither pushed" failure mode for local-path repos.
                # Remote URLs (https/ssh) require network and are left
                # to a future ``git ls-remote`` check.
                #
                # BUT only for UNPUSHED work. Per-lease executor workspaces
                # (repo-lease_<id>) are ephemeral and the sandbox re-inits git
                # in them, so once the commit is pushed its SHA is durably on
                # the remote yet frequently NOT reachable in that local path —
                # producing a false "not reachable" that fails an otherwise
                # publishable review. When repo.pushed is true, the commit's
                # reachability is authoritatively re-checked against origin at
                # publish time (verify_commit: git cat-file -e after fetch
                # origin), so the fragile local-path probe is both redundant
                # and wrong here. Run it only when the work was never pushed.
                repo_local_path = str(executor_repo.get("path") or "").strip()
                if repo_local_path and not executor_repo.get("pushed"):
                    from pathlib import Path as _RPath
                    from subprocess import run as _run, PIPE as _PIPE

                    candidate = _RPath(repo_local_path).expanduser()
                    if candidate.is_dir() and (candidate / ".git").exists():
                        try:
                            check = _run(
                                ["git", "rev-parse", "--verify", "%s^{commit}" % executor_sha],
                                cwd=str(candidate),
                                stdout=_PIPE,
                                stderr=_PIPE,
                                timeout=10,
                            )
                        except Exception:  # noqa: BLE001 - tooling missing → skip
                            check = None
                        if check is not None and check.returncode != 0:
                            problems.append(
                                "verdict %s executor head_sha %s not reachable in %s"
                                % (evidence.id, executor_sha, candidate)
                            )
                            continue
            if self._passed_verification_check_count(manifest) < 1:
                problems.append(
                    "verdict %s requires at least one independent passing check" % evidence.id
                )
                continue
            integration_problems = self._cooperative_review_integration_problems(
                reviewed_task, manifest
            )
            if integration_problems:
                problems.extend(
                    "verdict %s %s" % (evidence.id, problem) for problem in integration_problems
                )
                continue
            return evidence, []
        return None, problems

    def _cooperative_review_integration_problems(
        self, task: Task, verdict_manifest: JsonDict
    ) -> List[str]:
        coordination = ensure_json_object(ensure_json_object(task.metadata).get("coordination"))
        if coordination.get("phase") != "integration":
            return []
        child_outputs = coordination.get("child_outputs", [])
        expected = {
            str(item.get("executor_evidence_id") or "").strip()
            for item in child_outputs
            if isinstance(item, dict) and str(item.get("executor_evidence_id") or "").strip()
        }
        missing_outputs = [
            str(item.get("task_id") or "unknown").strip()
            for item in child_outputs
            if not isinstance(item, dict)
            or str(item.get("status") or "").strip() != "ready"
            or not str(item.get("executor_evidence_id") or "").strip()
            or not str(ensure_json_object(item.get("repo")).get("head_sha") or "").strip()
        ]
        integration = ensure_json_object(verdict_manifest.get("integration"))
        required = set(_metadata_string_list(integration.get("required_child_evidence_ids")))
        verified = set(_metadata_string_list(integration.get("verified_child_evidence_ids")))
        problems: List[str] = []
        if integration.get("status") != "pass":
            problems.append("cooperative integration verification must pass")
        if missing_outputs:
            problems.append(
                "cooperative integration has incomplete child outputs: %s"
                % ", ".join(sorted(set(missing_outputs)))
            )
        if not expected:
            problems.append("cooperative integration has no child evidence targets")
        if required != expected:
            problems.append(
                "cooperative integration required child evidence does not match task inputs"
            )
        if verified != expected:
            problems.append(
                "cooperative integration did not verify every child commit as an ancestor"
            )
        return problems

    def _verdict_value(self, evidence: Evidence) -> str:
        manifest = evidence.metadata.get("verification") or {}
        verdict = str(manifest.get("verdict") or "").strip().lower()
        # Fail closed: an unknown/malformed verdict must NOT auto-approve.
        return verdict if verdict in {"approved", "rejected"} else "rejected"

    def _retract_default_review(self, review: Review, actor: str, reason: str) -> None:
        now = utcnow()
        self.store.execute(
            """
            UPDATE reviews
            SET status = ?, reason = ?, completed_at = ?
            WHERE id = ? AND status = ?
            """,
            (
                ReviewStatus.RETRACTED.value,
                reason,
                now,
                review.id,
                ReviewStatus.PENDING.value,
            ),
        )
        # A reviewer that claimed this review is BUSY on the task; nothing
        # else will release it once the review is withdrawn.
        if not self._agent_has_active_lease(review.reviewer_agent_id):
            self.store.execute(
                """
                UPDATE agents SET status = ?, current_task_id = NULL, updated_at = ?
                WHERE id = ? AND status = ? AND current_task_id = ?
                """,
                (
                    AgentStatus.IDLE.value,
                    now,
                    review.reviewer_agent_id,
                    AgentStatus.BUSY.value,
                    review.task_id,
                ),
            )
        self._record_history(
            review.task_id,
            "task.review_retracted",
            actor,
            None,
            None,
            {
                "review_id": review.id,
                "reviewer_agent_id": review.reviewer_agent_id,
                "reason": reason,
            },
        )

    def _record_worker_evidence_verdict(
        self,
        task: Task,
        review: Review,
        executor_evidence: Evidence,
        actor: str,
    ) -> Optional[Evidence]:
        """Sign the hub-reviewer verdict for already-validated executor evidence.

        The review verdict is the worker's own evidence: the default workflow
        only gets here after ``_bound_review_evidence`` accepted it, which for
        repo changes includes the verifier's pass on the exact pushed commit.
        The hub re-runs nothing. It evaluates the task acceptance contract
        against the executor manifest and records that decision under the
        hub-reviewer key, so publication is authorised by a signed verdict
        whose signer is not the executor. Returns None when the key is
        unavailable; the caller waits and retries.
        """
        key = self._reviewer_attestation_key_for_signing(review.reviewer_agent_id, actor=actor)
        if key is None:
            return None
        executor_manifest = ensure_json_object(
            ensure_json_object(executor_evidence.metadata).get("verification")
        )
        repo = ensure_json_object(executor_manifest.get("repo"))
        acceptance = evaluate_acceptance(task.metadata, executor_manifest)
        # The independent judge (mac.task_judge) read the change against the
        # task. Its "not_met" is a semantic failure in its own right, and its
        # next steps become the feedback the next attempt starts from.
        judge = ensure_json_object(executor_manifest.get("judge"))
        if judge.get("verdict") == "not_met":
            judge_problem = "independent judge: not met: %s" % (judge.get("reason") or "")
            if judge.get("next"):
                judge_problem += "; next: %s" % judge["next"]
            acceptance = {
                **acceptance,
                "status": "fail",
                "problems": [*list(acceptance.get("problems") or []), judge_problem],
            }
        acceptance_pass = acceptance.get("status") in {"pass", "not_required"}
        coverage = evaluate_requirement_coverage(
            getattr(task, "description", None), executor_manifest
        )
        coverage_pass = coverage.get("status") in {"pass", REQUIREMENT_COVERAGE_NOT_REQUIRED}
        approved = acceptance_pass and coverage_pass
        verdict = "approved" if approved else "rejected"
        digest = str(executor_manifest.get("worktree_digest") or "").strip()
        if not digest.startswith("sha256:"):
            digest = "sha256:%s" % hashlib.sha256(executor_evidence.id.encode()).hexdigest()
        if approved:
            summary = "worker evidence validated; structural and task acceptance contracts passed"
            feedback = ""
        elif not acceptance_pass:
            summary = "task semantic acceptance failed: %s" % "; ".join(
                str(problem) for problem in acceptance.get("problems", [])
            )
            feedback = summary
        else:
            # Enumerated requirements are the task's definition of done. When
            # any is unmapped or unaddressed the hub-reviewer must not approve;
            # it names them so the next attempt can finish the work.
            summary = "task requirements not addressed: %s" % "; ".join(
                str(problem) for problem in coverage.get("problems", [])
            )
            feedback = summary
        manifest: Dict[str, Any] = {
            "schema": VERIFICATION_SCHEMA,
            "status": "complete",
            "evidence_type": "review_verdict",
            "verdict": verdict,
            "review_id": review.id,
            "reviewed_evidence_id": executor_evidence.id,
            "worktree_digest": digest,
            "verified_by": "worker_evidence_v1",
            "llm_model": "hub-reviewer",
            "llm": {
                "model": "hub-reviewer",
                "family": "deterministic",
                "provider": "hub",
            },
            "summary": summary,
            "review_status": {
                "structural": "pass",
                "semantic": "pass" if acceptance_pass else "fail",
            },
            "acceptance": acceptance,
            "requirement_coverage": coverage,
            "checks": [
                {
                    "name": "executor_evidence_contract",
                    "returncode": 0,
                    "status": "pass",
                },
                {
                    "name": "requirement_coverage",
                    "returncode": 0 if coverage_pass else 1,
                    "status": "pass" if coverage_pass else "fail",
                },
                {
                    "name": "task_acceptance",
                    "returncode": 0 if acceptance_pass else 1,
                    "status": "pass" if acceptance_pass else "fail",
                },
            ],
            "signed_by": review.reviewer_agent_id,
        }
        if feedback:
            manifest["feedback"] = feedback
        if repo:
            manifest["repo"] = repo
        if judge:
            manifest["judge"] = judge
        manifest["signature"] = sign_verification_manifest(key, manifest)
        evidence = self.add_evidence(
            task.id,
            "review",
            "mac://review-verdict/%s" % review.id,
            "worker evidence review: %s" % verdict,
            review.reviewer_agent_id,
            metadata={"returncode": 0, "verification": manifest},
        )
        if not approved:
            self._record_default_review_observation(
                task.id,
                (
                    "workflow.default_review.semantic_acceptance_failed"
                    if not acceptance_pass
                    else "workflow.default_review.requirement_coverage_failed"
                ),
                "warning",
                {
                    "review_id": review.id,
                    "reviewer_agent_id": review.reviewer_agent_id,
                    "executor_evidence_id": executor_evidence.id,
                    "verdict_evidence_id": evidence.id,
                    "reason": (
                        "semantic_acceptance_failed"
                        if not acceptance_pass
                        else "requirement_coverage_failed"
                    ),
                },
                actor,
            )
        return evidence

    def _ensure_hub_reviewer_agent(self, *, actor: str) -> Optional[Agent]:
        """Register (idempotently) the virtual hub-reviewer approval identity.

        The hub-reviewer runs nothing. It signs the review verdict that records
        the hub accepted the worker's validated evidence, so publication has an
        approved review whose signer is not the executor.
        """
        agent_id = DEFAULT_HUB_REVIEWER_AGENT_ID
        try:
            existing = self.get_agent(agent_id)
        except NotFoundError:
            existing = None
        if (
            existing is not None
            and self._agent_is_hub_review_verifier(existing)
            and existing.health_status == HealthStatus.HEALTHY.value
            and existing.status in {AgentStatus.IDLE.value, AgentStatus.BUSY.value}
        ):
            # Registered and usable. Its signing key self-heals at signing
            # time (_reviewer_attestation_key_for_signing), so a sweep does
            # not re-register it for every task it touches.
            return existing
        try:
            machine = self.register_machine(
                "operator-review",
                labels={
                    "source": "mac-hub-reviewer",
                    "role": "hub-reviewer",
                    "virtual": True,
                },
                resources={"virtual": True, "review": {"mode": "worker_evidence"}},
                trusted=True,
                machine_id=DEFAULT_HUB_REVIEWER_MACHINE_ID,
            )
            reviewer = self.register_agent(
                machine.id,
                DEFAULT_HUB_REVIEWER_AGENT_NAME,
                capabilities=["review"],
                resources={
                    "virtual": True,
                    "hub_review_verifier": {
                        "schema": HUB_REVIEW_VERIFIER_RESOURCE_SCHEMA,
                        "enabled": True,
                        "mode": "worker_evidence",
                    },
                },
                agent_id=agent_id,
                actor=actor,
            )
            try:
                self.ensure_hub_reviewer_attestation_key(reviewer.id, actor=actor)
            except ValidationError as exc:
                self.observability.record_log(
                    "workflow.default_review.hub_reviewer_key_unhealthy",
                    level="error",
                    layer="control_plane",
                    source="default-review-workflow",
                    subject_type="agent",
                    subject_id=reviewer.id,
                    detail={"actor": actor, "error": str(exc)[:300]},
                )
            return self.get_agent(reviewer.id)
        except Exception as exc:  # noqa: BLE001 - reviewer setup must not break review sweeps.
            self.observability.record_log(
                "workflow.default_review.hub_reviewer_register_failed",
                level="warning",
                layer="control_plane",
                source="default-review-workflow",
                subject_type="agent",
                subject_id=agent_id,
                detail={"actor": actor, "error": str(exc)[:300]},
            )
            return None

    def _agent_is_hub_review_verifier(self, agent: Agent) -> bool:
        marker = ensure_json_object(ensure_json_object(agent.resources).get("hub_review_verifier"))
        return (
            marker.get("schema") == HUB_REVIEW_VERIFIER_RESOURCE_SCHEMA
            and marker.get("enabled") is not False
        )

    def _default_reviewer_unavailable_reason(
        self,
        task: Task,
        agent: Agent,
        *,
        executor_agent_id: Optional[str] = None,
        review_policy: Optional[JsonDict] = None,
    ) -> Optional[str]:
        if agent.id in self._coordination_excluded_agent_ids(task):
            return "reviewer_cooperative_family_participant"
        if agent.health_status != HealthStatus.HEALTHY.value:
            return "reviewer_unhealthy"
        if agent.status not in {AgentStatus.IDLE.value, AgentStatus.BUSY.value}:
            return "reviewer_not_available"
        hub_review_verifier = self._agent_is_hub_review_verifier(agent)
        if (
            metadata_declares_read_only_report_repository(task.metadata)
            and not hub_review_verifier
            and not agent_has_read_only_report_repository_executor(agent.resources)
        ):
            return "reviewer_report_repository_executor_missing"
        if not hub_review_verifier and not self._agent_seen_recently(
            agent, self._default_reviewer_stale_after_seconds()
        ):
            return "reviewer_stale"
        if self.reviews.agent_has_owned_task(task.id, agent.id):
            return "reviewer_previously_owned_task"
        if executor_agent_id is not None and agent.id == executor_agent_id:
            return "reviewer_created_executor_evidence"
        if "review" not in set(agent.capabilities):
            return "reviewer_missing_capability"
        policy = review_policy if review_policy is not None else self._default_review_policy(task)
        target_agent_id = str(
            policy.get("target_agent_id") or policy.get("reviewer_agent_id") or ""
        ).strip()
        if target_agent_id and agent.id != target_agent_id:
            return "reviewer_not_target_agent"
        target_agent_name = str(
            policy.get("target_agent_name") or policy.get("reviewer_agent_name") or ""
        ).strip()
        if target_agent_name and agent.name != target_agent_name:
            return "reviewer_not_target_agent"
        required = set(self._default_review_required_capabilities(task, policy))
        missing = sorted(required - set(agent.capabilities))
        if missing:
            return "reviewer_missing_capabilities:%s" % ",".join(missing)
        task_tenant = self._task_tenant_id(task)
        executor_persona_slug = self._task_executor_persona_slug(task)
        agent_tenant, agent_persona_slug = self._agent_tenant_and_persona(agent)
        if task_tenant is not None:
            if agent_tenant is None:
                # Headless worker (no hermes_instance_id => no persona
                # tenant). Persona-boundary tenancy fails closed for these
                # agents, which would park every tenant-scoped Hermes task
                # forever in needs_review. Fall back to the hardware
                # boundary — the same gate the executor path uses
                # (_agent_available_for) — so a headless reviewer on a
                # machine whose tenant policy permits the task's tenant
                # stays eligible, while one on a disallowed machine is
                # still refused.
                try:
                    machine = self.get_machine(agent.machine_id)
                except NotFoundError:
                    return "reviewer_wrong_tenant"
                if not self._machine_allows_tenant(machine, task_tenant):
                    return "reviewer_wrong_tenant"
            elif agent_tenant != task_tenant:
                return "reviewer_wrong_tenant"
        if (
            executor_persona_slug is not None
            and agent_persona_slug is not None
            and agent_persona_slug == executor_persona_slug
        ):
            return "reviewer_same_persona"
        if hub_review_verifier:
            return None
        access_state, learning = self._reviewer_repository_access_state(task, agent.id)
        if access_state == "failure":
            host = str((learning or {}).get("repository_host") or "unknown")
            failure_class = str((learning or {}).get("failure_class") or "authentication")
            return "reviewer_repository_access_%s:%s" % (failure_class, host)
        return None

    def _reviewer_repository_access_state(
        self,
        task: Task,
        reviewer_agent_id: str,
    ) -> Tuple[str, Optional[JsonDict]]:
        remote = task_repository_remote(task)
        host = repository_host(remote)
        if not host or host == "local":
            return "unknown", None
        try:
            failure_cooldown = max(
                0,
                int(
                    os.environ.get(
                        "MAC_REPOSITORY_ACCESS_FAILURE_COOLDOWN_SECONDS",
                        "1800",
                    )
                ),
            )
        except ValueError:
            failure_cooldown = 1800
        try:
            success_ttl = max(
                0,
                int(
                    os.environ.get(
                        "MAC_REPOSITORY_ACCESS_SUCCESS_TTL_SECONDS",
                        "86400",
                    )
                ),
            )
        except ValueError:
            success_ttl = 86400
        records = self.memory.search_memory(
            subject_type="agent",
            subject_id=reviewer_agent_id,
            record_type=REPOSITORY_ACCESS_RECORD_TYPE,
            limit=50,
            order="desc",
        )
        state, learning = repository_access_state(
            records,
            project=task.project or "default",
            host=host,
            operation="review_clone",
            failure_cooldown_seconds=failure_cooldown,
            success_ttl_seconds=success_ttl,
        )
        return state, learning

    def _default_reviewer_stale_after_seconds(self) -> int:
        raw = (
            os.environ.get("MAC_DEFAULT_REVIEWER_STALE_AFTER_SECONDS", "").strip()
            or os.environ.get("MAC_AGENT_STALE_AFTER_SECONDS", "").strip()
        )
        if not raw:
            return 300
        try:
            return max(1, int(raw))
        except ValueError:
            return 300

    def _agent_seen_recently(self, agent: Agent, stale_after_seconds: int) -> bool:
        try:
            seen_at = parse_time(agent.last_seen_at)
            now = parse_time(utcnow())
        except Exception:  # noqa: BLE001 - malformed timestamps should fail closed.
            return False
        if seen_at.tzinfo is None and now.tzinfo is not None:
            now = now.replace(tzinfo=None)
        if seen_at.tzinfo is not None and now.tzinfo is None:
            seen_at = seen_at.replace(tzinfo=None)
        return (now - seen_at).total_seconds() <= max(1, int(stale_after_seconds))

    def _agent_tenant_and_persona(self, agent: Agent) -> Tuple[Optional[str], Optional[str]]:
        """Return ``(tenant_id, persona_slug)`` for an agent, both
        optional. Used by the reviewer-selection guards (tenancy +
        anti-collusion). Agents without a hermes_instance_id have
        neither and are treated as ineligible by the reviewer picker
        when the task is tenant-scoped."""
        if not agent.persona_instance_id:
            return None, None
        try:
            instance = self.identity.get_persona_instance(agent.persona_instance_id)
        except NotFoundError:
            return None, None
        if not instance.persona_id:
            return instance.tenant_id, None
        try:
            persona = self.identity.get_persona(instance.persona_id)
        except NotFoundError:
            return instance.tenant_id, None
        slug = persona.name.strip().lower().replace(" ", "-").replace("_", "-") or None
        return instance.tenant_id, slug

    def _reviewer_assignment_problem(self, task: Task, reviewer: Agent) -> Optional[str]:
        """Apply the same complete eligibility policy to every assignment path."""
        executor_agent_id = self.reviews.latest_executor_evidence_author(task.id)
        reason = self._default_reviewer_unavailable_reason(
            task,
            reviewer,
            executor_agent_id=executor_agent_id,
            review_policy=self._default_review_policy(task),
        )
        if reason is None:
            return None
        readable = {
            "reviewer_same_persona": "reviewer and executor use the same persona",
            "reviewer_wrong_tenant": "reviewer is outside the task tenant boundary",
            "reviewer_report_repository_executor_missing": (
                "reviewer lacks the controller-verified per-task OpenShell report executor"
            ),
            "reviewer_cooperative_family_participant": (
                "reviewer executed another task in the same cooperative work family"
            ),
        }
        return readable.get(reason, reason.replace("_", " "))

    def _task_executor_persona_slug(self, task: Task) -> Optional[str]:
        """Find the persona slug of whichever agent owned the task last
        (the executor). Used by anti-collusion. Returns None when the
        task has no recorded owner — in that case no executor-side
        persona constraint applies."""
        executor_agent_id: Optional[str] = task.owner_agent_id
        if executor_agent_id is None:
            # Look for the last lease against this task — it identifies
            # the executor even after submit-for-review releases owner.
            row = self.store.query_one(
                """
                SELECT agent_id FROM leases
                WHERE task_id = ?
                ORDER BY created_at DESC, id DESC
                LIMIT 1
                """,
                (task.id,),
            )
            if row is not None:
                executor_agent_id = row["agent_id"]
        if executor_agent_id is None:
            return None
        try:
            executor = self.get_agent(executor_agent_id)
        except NotFoundError:
            return None
        _, slug = self._agent_tenant_and_persona(executor)
        return slug

    def _default_publication_target(self, task: Task) -> Optional[str]:
        """Resolve the publication target from task metadata or return None.

        Returns ``None`` when no operator-set target is available
        (mac-w29). Previously this synthesized ``mac://tasks/{id}`` which
        is filler — no resolver exists for that URI. The auto-review
        workflow now treats ``None`` as "no publication destination
        configured; leave the approved task in review and emit a waiting
        observability event."
        """
        metadata = task.metadata
        report_deliverable = metadata_declares_report_deliverable(metadata)

        def eligible(target: str) -> bool:
            return not (report_deliverable and target.startswith("git://"))

        for key in ("publication_target", "publish_target"):
            value = metadata.get(key)
            if isinstance(value, str) and value.strip() and eligible(value.strip()):
                return value.strip()
        publication = metadata.get("publication")
        if isinstance(publication, dict):
            target = publication.get("target")
            if isinstance(target, str) and target.strip() and eligible(target.strip()):
                return target.strip()
        acc_metadata = metadata.get("acc_metadata")
        if isinstance(acc_metadata, dict):
            beads_id = acc_metadata.get("beads_id")
            if isinstance(beads_id, str) and beads_id.strip():
                return "beads://%s" % beads_id.strip()
        # Fall back to the task's registered project metadata so an
        # operator can configure a single publication target per project
        # (e.g. for autonomous coding tasks that all complete the same
        # way) instead of stamping every task individually.
        project_target = self._project_publication_target(task)
        if project_target and eligible(project_target):
            return project_target
        # Fleet-wide default (opt-in): when set, routine approved tasks publish
        # via this target and auto-complete instead of parking in review for
        # want of a per-task/per-project destination. Unset => unchanged (mac-w29
        # hold). e.g. MAC_DEFAULT_PUBLICATION_TARGET=git://main
        #
        # A *git* fleet-default only applies where the HUB can actually publish
        # (origin pins a clonable url, or a hub-local repository_path exists);
        # applying it to a non-publishable task would raise in the git publish
        # (_publish_git_target_if_needed) and block the task. Non-git defaults
        # apply to all.
        fleet_default = (os.environ.get("MAC_DEFAULT_PUBLICATION_TARGET") or "").strip()
        if fleet_default and (
            not fleet_default.startswith("git://") or self._task_git_publishable(task)
        ):
            return fleet_default
        return None

    def _task_git_publishable(self, task: Task) -> bool:
        """True if a git publish/merge can be attempted for this task — i.e. it is
        a repo task (origin pins a repo url/path, or a repository_contract). The
        publish resolves a hub-usable repo from origin.repository_url, a hub-local
        origin.repository_path, or the remote the worker pushed to (from the
        evidence), so a repo task need not have a hub-local path. Non-repo
        (operator) tasks return False so a git fleet-default never blocks them."""
        metadata = ensure_json_object(task.metadata)
        if metadata_declares_report_deliverable(metadata):
            return False
        origin = ensure_json_object(metadata.get("origin"))
        if str(origin.get("repository_url") or "").strip():
            return True
        if str(origin.get("repository_path") or "").strip():
            return True
        contract = ensure_json_object(origin.get("repository_contract"))
        return bool(
            str(contract.get("project") or "").strip()
            or str(contract.get("canonical_remote_url") or "").strip()
        )

    def _project_publication_target(self, task: Task) -> Optional[str]:
        project_name = str(getattr(task, "project", "") or "").strip()
        if not project_name:
            return None
        try:
            record = self.get_project_record(project_name)
        except NotFoundError:
            return None
        meta = ensure_json_object(record.metadata)
        for key in ("publication_target", "publish_target"):
            value = meta.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        publication = meta.get("publication")
        if isinstance(publication, dict):
            target = publication.get("target")
            if isinstance(target, str) and target.strip():
                return target.strip()
        return None

    def _record_publication_block(
        self,
        task_id: str,
        *,
        reason: str,
        review_id: Optional[str] = None,
        evidence_id: Optional[str] = None,
        actor: str = "control-plane",
    ) -> None:
        """Stamp an approved task with WHY it cannot leave review.

        Approval does not complete a task: ``-> COMPLETED`` happens
        only inside :meth:`publish_task`, which needs a resolved publication
        target.  When none resolves the task parks, and until this marker
        existed the reason lived only in a code comment and a transient
        observability event — the task itself carried nothing, so a parked task
        was indistinguishable from work in flight (task_ce6c8ea3: four tasks sat
        approved-and-undeliverable from 2026-08-01 to 2026-08-05, and only
        surfaced because someone happened to ask what was executing).

        ``since`` is set once and never refreshed.  Re-reviewing a task that is
        already parked must not restart its clock, or a task re-examined every
        few hours would never look old enough to report.
        """
        try:
            task = self.get_task(task_id)
        except NotFoundError:
            return
        metadata = ensure_json_object(task.metadata)
        existing = ensure_json_object(metadata.get("publication_block"))
        if existing.get("reason") == reason:
            return
        block: JsonDict = {
            "schema": PUBLICATION_BLOCK_SCHEMA,
            "reason": reason,
            "since": str(existing.get("since") or utcnow()),
        }
        if review_id:
            block["review_id"] = str(review_id)
        if evidence_id:
            block["evidence_id"] = str(evidence_id)
        metadata["publication_block"] = block
        self._persist_task_metadata_narrow(
            task_id,
            metadata,
            actor=actor,
            detail={"publication_block": reason},
        )

    def parked_reviewing_tasks(
        self,
        *,
        min_age_seconds: float = 0.0,
        limit: int = 50,
    ) -> List[JsonDict]:
        """Approved tasks that cannot reach COMPLETED as things stand.

        A task is parked when it is approved and still in review, nobody holds
        it, and no publication target resolves for it — so nothing downstream
        will ever move it on. The default workflow approves in NEEDS_REVIEW and
        stamps ``metadata.publication_block`` when it parks; a legacy or
        human-reviewed task parks in REVIEWING, possibly without the marker.  Resolution is re-evaluated live rather than trusted from
        the stored marker, because the marker is written when a task parks and
        an operator may have set ``metadata.publication_target`` (or a project
        target, or the fleet default) since; such a task is recoverable and must
        not be reported as stuck.  Evaluating live also means tasks that parked
        BEFORE the marker existed are still found, which matters — the four
        tasks that motivated this have no marker.

        Age is measured from the marker's ``since`` when present and from
        ``updated_at`` otherwise, so a task keeps its original park time.
        """
        rows = self.store.query_all(
            "SELECT id FROM tasks WHERE owner_agent_id IS NULL AND ("
            "state = ? OR (state = ? AND "
            "json_extract(metadata, '$.publication_block.reason') IS NOT NULL)"
            ") ORDER BY updated_at",
            (TaskState.REVIEWING.value, TaskState.NEEDS_REVIEW.value),
        )
        now = parse_time(utcnow())
        parked: List[JsonDict] = []
        for row in rows:
            try:
                task = self.get_task(str(row["id"]))
            except NotFoundError:
                continue
            if self._default_publication_target(task) is not None:
                continue
            metadata = ensure_json_object(task.metadata)
            block = ensure_json_object(metadata.get("publication_block"))
            since = str(block.get("since") or task.updated_at or utcnow())
            try:
                age_seconds = (now - parse_time(since)).total_seconds()
            except (TypeError, ValueError):
                age_seconds = 0.0
            if age_seconds < min_age_seconds:
                continue
            parked.append(
                {
                    "id": task.id,
                    "title": task.title,
                    "project": task.project,
                    "reason": str(block.get("reason") or "no_publication_target"),
                    "since": since,
                    "age_seconds": round(age_seconds, 3),
                }
            )
        parked.sort(key=lambda item: item["since"])
        return parked[:limit]

    def _record_default_review_observation(
        self,
        task_id: str,
        name: str,
        level: str,
        detail: JsonDict,
        actor: str,
    ) -> None:
        self.observability.record_log(
            name,
            level=level,
            layer="control_plane",
            source="default-review-workflow",
            subject_type="task",
            subject_id=task_id,
            detail={"actor": actor, **detail},
        )

    def _record_project_failure_lesson(
        self,
        task_id: str,
        *,
        evidence_type: str,
        error_signature: str,
        signals: Optional[JsonDict] = None,
        evidence_id: Optional[str] = None,
    ) -> None:
        """Persist a hub-side, project-scoped ``mac.deployment_learning.v1``
        failure lesson so the next execution run on this project recalls it.

        The executor records deployment lessons for failed *runs*, but review
        rejections and hub-side terminal failures produced no lesson — so the
        fleet never learned from rejected or force-failed work. The record
        shape matches the executor's ``build_learning_record`` so
        ``recall_deployment_lessons`` renders and injects it unchanged.
        Best-effort: telemetry-only, never breaks the caller.
        """
        try:
            task = self.get_task(task_id)
        except Exception:  # noqa: BLE001 - lesson recording must not break the workflow.
            return
        try:
            project = self._hermes_task_project_key(task) or (task.project or "unassigned")
            metadata = ensure_json_object(task.metadata)
            origin = metadata.get("origin") if isinstance(metadata, dict) else {}
            repo_name = str(origin.get("repository_name") or "") if isinstance(origin, dict) else ""
            content = {
                "schema": "mac.deployment_learning.v1",
                "task_id": task.id,
                "task_title": task.title,
                "project": project,
                "repository": repo_name,
                "evidence_type": evidence_type,
                "outcome": "failure",
                "signals": signals or {},
                "error_signature": error_signature or "",
                "at": utcnow(),
            }
            self.add_memory(
                task_id=task.id,
                subject_type="project",
                subject_id=project,
                # Matches the executor's DEPLOYMENT_LEARNING_PREFIX contract so
                # recall_deployment_lessons (which filters by this record_type
                # prefix + project) picks it up.
                record_type="deployment_learning:%s" % project,
                content=json_dumps(content),
                evidence_id=evidence_id,
                created_by="mac-hub-review",
            )
        except Exception:  # noqa: BLE001 - best-effort durable learning.
            import logging

            logging.getLogger(__name__).warning(
                "could not record project failure lesson for %s", task_id, exc_info=True
            )

    def _set_agent_idle(self, agent_id: str, conn: Any = None) -> None:
        now = utcnow()
        writer = conn if conn is not None else self.store
        remaining = writer.execute(
            """
            SELECT t.id AS task_id
            FROM leases l
            JOIN tasks t ON t.lease_id = l.id
            WHERE l.agent_id = ?
              AND l.status = ?
              AND t.owner_agent_id = ?
              AND t.state IN (?, ?)
            ORDER BY l.created_at, l.id
            LIMIT 1
            """,
            (
                agent_id,
                LeaseStatus.ACTIVE.value,
                agent_id,
                TaskState.CLAIMED.value,
                TaskState.RUNNING.value,
            ),
        ).fetchone()
        if remaining is None:
            status = AgentStatus.IDLE.value
            current_task_id = None
        else:
            status = AgentStatus.BUSY.value
            current_task_id = str(remaining["task_id"])
        writer.execute(
            "UPDATE agents SET status = ?, current_task_id = ?, updated_at = ? WHERE id = ?",
            (status, current_task_id, now, agent_id),
        )

    def _agent_held_by_deployment(self, agent: Agent) -> bool:
        """Whether a deploy is holding this worker down rather than its host leaving."""

        if not agent.dispatch_hold:
            return False
        reason = str(agent.dispatch_hold_reason or "")
        return reason.startswith(DEPLOYMENT_HOLD_REASON_PREFIXES)

    def _agent_has_active_lease(self, agent_id: str) -> bool:
        row = self.store.query_one(
            """
            SELECT 1 FROM leases l
            JOIN tasks t ON t.lease_id = l.id
            WHERE l.agent_id = ?
              AND l.status = ?
              AND t.owner_agent_id = ?
            LIMIT 1
            """,
            (agent_id, LeaseStatus.ACTIVE.value, agent_id),
        )
        return row is not None

    def _agent_active_lease_count(self, agent_id: str) -> int:
        row = self.store.query_one(
            """
            SELECT COUNT(*) AS count FROM leases l
            JOIN tasks t ON t.lease_id = l.id
            WHERE l.agent_id = ?
              AND l.status = ?
              AND t.owner_agent_id = ?
            """,
            (agent_id, LeaseStatus.ACTIVE.value, agent_id),
        )
        return int(row["count"] if row is not None else 0)

    def _agent_capacity(self, agent: Agent) -> int:
        for key in ("capacity", "max_concurrent_tasks"):
            value = agent.resources.get(key)
            if value is not None:
                return max(1, int(value))
        return 1

    # --- service-role election (media-01) -------------------------------

    def _agent_eligible_for_service(self, agent: Agent, role: ServiceRole) -> bool:
        """Capability + hardware fit (uses reported GPU hw + the catalog VRAM
        floor). Capacity is checked separately in the sync loop."""
        if not set(role.required_capabilities).issubset(set(agent.capabilities or [])):
            return False
        hw = agent.resources.get("hardware") if isinstance(agent.resources, dict) else None
        if role.hardware_requirements:
            from mac.roles_service import machine_hardware_satisfies

            ok, _reasons = machine_hardware_satisfies(role.hardware_requirements, hw or {})
            if not ok:
                return False
        if role.model_id:
            try:
                from mac.local_gen_catalog import get_model, models_for_hardware

                model = get_model(role.model_id)
                if model is not None and model not in models_for_hardware(hw):
                    return False
            except Exception:  # noqa: BLE001 - catalog is optional
                pass
        return True

    @staticmethod
    def _agent_service_claim_eligibility_reason(agent: Agent) -> Optional[str]:
        """Return the durable agent-state fence blocking service-role claims."""

        if agent.deleted_at:
            return "agent_decommissioned"
        if agent.dispatch_hold:
            return "agent_dispatch_held"
        if agent.status not in {AgentStatus.IDLE.value, AgentStatus.BUSY.value}:
            return "agent_status_unavailable"
        if agent.health_status != HealthStatus.HEALTHY.value:
            return "agent_health_unavailable"
        return None

    def _service_holder_live(self, agent_id: str) -> bool:
        try:
            agent = self.get_agent(agent_id)
        except Exception:  # noqa: BLE001
            return False
        return self._agent_service_claim_eligibility_reason(agent) is None

    def sync_agent_service_claims(
        self, agent_id: str, willing_ops: Iterable[str], *, lease_seconds: int = 1800
    ) -> JsonDict:
        """A capable host declares the ops it's willing+able to run; the hub
        renews its still-willing held ops, releases ones it no longer wants, and
        claims new eligible ops up to the agent's capacity (so ops spread to
        hosts with headroom). Returns the authoritative held-op set.

        Self-driving: worker syncs (every ~30s) seed desired roles + reap stale
        claims, so the subsystem doesn't depend on a periodic /dispatch/tick."""
        self._ensure_service_roles_seeded()
        self.service_roles.expire_service_claims()
        willing = {str(op).strip() for op in (willing_ops or []) if str(op).strip()}
        with self.store.transaction() as conn:
            # Global lock order for agent-owned state is agent row first, then
            # the agent's service claims.  This is the same first fence used by
            # decommissioning and credential lifecycle operations.  On SQLite,
            # BEGIN IMMEDIATE serializes the writer; on PostgreSQL the no-op
            # UPDATE retains a row lock until this transaction commits.
            locked = conn.execute(
                "UPDATE agents SET updated_at = updated_at WHERE id = ? AND deleted_at IS NULL",
                (agent_id,),
            )
            if locked.rowcount != 1:
                row = conn.execute(
                    "SELECT deleted_at FROM agents WHERE id = ?", (agent_id,)
                ).fetchone()
                if row is None:
                    raise NotFoundError("agent not found: %s" % agent_id)
                raise ValidationError(
                    "agent %s was decommissioned at %s" % (agent_id, row["deleted_at"])
                )
            agent_row = conn.execute("SELECT * FROM agents WHERE id = ?", (agent_id,)).fetchone()
            agent = self._agent_from_row(agent_row)
            capacity = self._agent_capacity(agent)

            role_rows = conn.execute(
                "SELECT * FROM service_roles WHERE enabled = 1 AND tenant_id IS NULL ORDER BY id"
            ).fetchall()
            roles_by_op: Dict[str, ServiceRole] = {}
            for row in role_rows:
                role = self.service_roles._role_from_row(row)
                roles_by_op.setdefault(role.op, role)

            # Lock this agent's active claims only after its eligibility row.
            # Every release, renewal and acquisition below uses this same
            # connection, closing the stale GET -> separate write TOCTOU.
            conn.execute(
                "UPDATE service_claims SET updated_at = updated_at "
                "WHERE agent_id = ? AND status = ?",
                (agent_id, ServiceClaimStatus.ACTIVE.value),
            )
            claim_rows = conn.execute(
                "SELECT c.*, r.op AS role_op FROM service_claims c "
                "LEFT JOIN service_roles r ON r.id = c.service_role_id "
                "WHERE c.agent_id = ? AND c.status = ? ORDER BY c.id",
                (agent_id, ServiceClaimStatus.ACTIVE.value),
            ).fetchall()

            blocked_reason = self._agent_service_claim_eligibility_reason(agent)
            if blocked_reason is not None:
                # A held/draining/unhealthy worker is not merely denied new
                # claims: any old advertisement is withdrawn in this same
                # eligibility transaction and therefore cannot be renewed.
                conn.execute(
                    "UPDATE service_claims SET status = ?, updated_at = ? "
                    "WHERE agent_id = ? AND status = ?",
                    (
                        ServiceClaimStatus.RELEASED.value,
                        utcnow(),
                        agent_id,
                        ServiceClaimStatus.ACTIVE.value,
                    ),
                )
                return {
                    "held": [],
                    "managed": sorted(roles_by_op.keys()),
                    "capacity": capacity,
                    "eligible": False,
                    "eligibility_reason": blocked_reason,
                }

            held_ops: Dict[str, Any] = {}
            now = utcnow()
            for claim in claim_rows:
                op = str(claim["role_op"] or "")
                if not op or op in held_ops or op not in willing or op not in roles_by_op:
                    conn.execute(
                        "UPDATE service_claims SET status = ?, updated_at = ? "
                        "WHERE id = ? AND agent_id = ? AND status = ?",
                        (
                            ServiceClaimStatus.RELEASED.value,
                            now,
                            claim["id"],
                            agent_id,
                            ServiceClaimStatus.ACTIVE.value,
                        ),
                    )
                    continue
                held_ops[op] = claim

            expires_at = (parse_time(now) + timedelta(seconds=int(lease_seconds))).isoformat()
            for op, claim in list(held_ops.items()):
                renewed = conn.execute(
                    "UPDATE service_claims SET expires_at = ?, updated_at = ? "
                    "WHERE id = ? AND agent_id = ? AND status = ?",
                    (
                        expires_at,
                        now,
                        claim["id"],
                        agent_id,
                        ServiceClaimStatus.ACTIVE.value,
                    ),
                )
                if renewed.rowcount != 1:
                    del held_ops[op]

            active_lease_row = conn.execute(
                "SELECT COUNT(*) AS count FROM leases l "
                "JOIN tasks t ON t.lease_id = l.id "
                "WHERE l.agent_id = ? AND l.status = ? "
                "AND t.owner_agent_id = ?",
                (agent_id, LeaseStatus.ACTIVE.value, agent_id),
            ).fetchone()
            load = len(held_ops) + int(
                active_lease_row["count"] if active_lease_row is not None else 0
            )
            candidates = [
                op
                for op in willing
                if op not in held_ops and op in roles_by_op and roles_by_op[op].enabled
            ]
            holder_counts = {
                str(row["service_role_id"]): int(row["count"])
                for row in conn.execute(
                    "SELECT service_role_id, COUNT(*) AS count "
                    "FROM service_claims WHERE status = ? "
                    "GROUP BY service_role_id",
                    (ServiceClaimStatus.ACTIVE.value,),
                ).fetchall()
            }

            for op in sorted(
                candidates,
                key=lambda value: (holder_counts.get(roles_by_op[value].id, 0), value),
            ):
                if load >= capacity:
                    break
                role = roles_by_op[op]
                if not self._agent_eligible_for_service(agent, role):
                    continue
                claim_id = new_id("sclaim")
                conn.execute(
                    "INSERT INTO service_claims ("
                    "id, service_role_id, agent_id, status, expires_at, "
                    "created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?) "
                    "ON CONFLICT DO NOTHING",
                    (
                        claim_id,
                        role.id,
                        agent_id,
                        ServiceClaimStatus.ACTIVE.value,
                        expires_at,
                        now,
                        now,
                    ),
                )
                active = conn.execute(
                    "SELECT id FROM service_claims "
                    "WHERE service_role_id = ? AND agent_id = ? AND status = ?",
                    (role.id, agent_id, ServiceClaimStatus.ACTIVE.value),
                ).fetchone()
                if active is None:
                    continue
                held_ops[op] = active
                holder_counts[role.id] = holder_counts.get(role.id, 0) + 1
                load += 1

            # "managed" = ops that have a service_role (election active). Ops
            # not managed remain advertised unconditionally for compatibility.
            return {
                "held": sorted(held_ops.keys()),
                "managed": sorted(roles_by_op.keys()),
                "capacity": capacity,
                "eligible": True,
                "eligibility_reason": None,
            }

    def _ensure_service_roles_seeded(self) -> None:
        """Idempotently seed the desired ops from MAC_SERVICE_ROLE_OPS (opt-in;
        unset = no election). Driven by both worker syncs and the tick."""
        ops_env = (os.environ.get("MAC_SERVICE_ROLE_OPS") or "").strip()
        if not ops_env:
            return
        wanted = [o.strip() for o in ops_env.split(",") if o.strip()]
        existing = {r.op for r in self.service_roles.desired_services(tenant_id=None)}
        if any(o not in existing for o in wanted):
            self.seed_service_roles(wanted)

    def reconcile_service_roles(self) -> JsonDict:
        """Periodic (called from tick): seed desired ops from MAC_SERVICE_ROLE_OPS
        (opt-in; unset = no election, agents advertise as before), expire silent/
        overloaded holders, drop offline holders, and report every desired op
        with zero live holders as ``unheld``."""
        self._ensure_service_roles_seeded()
        expired = self.service_roles.expire_service_claims()
        unheld: List[str] = []
        for role in self.service_roles.desired_services(tenant_id=None):
            live = [
                c
                for c in self.service_roles.list_active_claims(role_id=role.id)
                if self._service_holder_live(c.agent_id)
            ]
            for claim in self.service_roles.list_active_claims(role_id=role.id):
                if not self._service_holder_live(claim.agent_id):
                    self.service_roles.release_service_claim(claim.id, reason="holder_offline")
            if not live:
                unheld.append(role.op)
        return {"expired": len(expired), "unheld": unheld}

    def reconcile_openshell_task_sandbox_lifecycle(
        self,
        *,
        trigger: str = "periodic",
        apply: bool = False,
        openshell_bin: Optional[str] = None,
    ) -> JsonDict:
        """Controller-owned GC for orphaned OpenShell task sandboxes.

        Called after a task ownership change, finalization, cancellation, or
        worker replacement (``trigger``), or on a periodic sweep. A Ready task
        sandbox is reaped only when THIS controller's authoritative task/lease
        store proves the recorded lease is no longer live for the sandbox's
        ``mac.task.id`` (task terminal, unleased, superseded lease, or expired
        lease). Orphan status is never inferred from agent idleness or
        host-local PID liveness. Every candidate carries the accountable tuple
        (task id, lease id, sandbox name, ownership observation, age, action,
        outcome); the returned report is secret-free. Best-effort: a missing
        ``openshell`` binary or list failure is caught and reported, never
        raised, so lifecycle transitions are not blocked.
        """

        from mac.openshell_sandbox_gc import reconcile_task_sandbox_lifecycle

        binary = (
            openshell_bin
            or (os.environ.get("MAC_OPENSHELL_BIN") or "openshell").strip()
            or "openshell"
        )

        def _lookup_task(task_id: str) -> Optional[Dict[str, Any]]:
            if not task_id:
                return None
            try:
                return self.get_task(task_id).to_dict()
            except NotFoundError:
                # A task the store cannot resolve fails closed downstream (the
                # sandbox is preserved).
                return None

        try:
            return reconcile_task_sandbox_lifecycle(
                _lookup_task,
                trigger=trigger,
                openshell_bin=binary,
                apply=apply,
            )
        except Exception as exc:  # noqa: BLE001 - lifecycle must not be blocked
            logging.getLogger(__name__).warning(
                "OpenShell task sandbox lifecycle GC failed (trigger=%s): %s",
                trigger,
                exc,
            )
            return {
                "schema": "mac.openshell.sandbox_lifecycle_gc.v1",
                "trigger": str(trigger or "").strip().lower(),
                "dry_run": not apply,
                "scanned": 0,
                "protected": 0,
                "candidates": [],
                "deleted": [],
                "failures": [],
                "error": str(exc)[-1000:],
            }

    def seed_service_roles(self, ops: Iterable[Any]) -> int:
        """Idempotently seed/enable a desired service_role per op. Each op is a
        dict {op, model_id, capabilities?} or a bare op string (model from the
        catalog)."""
        from mac.local_gen_catalog import LOCAL_GEN_MODELS

        by_op_default = {}
        for m in LOCAL_GEN_MODELS:
            if m.routable:
                by_op_default.setdefault(m.op, m.id)
        count = 0
        for spec in ops:
            if isinstance(spec, dict):
                op = str(spec.get("op") or "").strip()
                model_id = spec.get("model_id") or by_op_default.get(op)
                caps = spec.get("capabilities") or ["gpu"]
            else:
                op = str(spec).strip()
                model_id = by_op_default.get(op)
                caps = ["gpu"]
            if not op:
                continue
            self.service_roles.upsert_role(op, model_id=model_id, required_capabilities=caps)
            count += 1
        return count

    def _task_tenant_id(self, task: Task) -> Optional[str]:
        origin = task.metadata.get("origin")
        if isinstance(origin, dict) and origin.get("tenant_id"):
            return str(origin["tenant_id"])
        tenant_id = task.metadata.get("tenant_id")
        return str(tenant_id) if tenant_id else None

    def _machine_allows_tenant(self, machine: Machine, tenant_id: Optional[str]) -> bool:
        policy = machine.labels.get("tenant_policy") or {}
        if not isinstance(policy, dict):
            return True
        mode = str(policy.get("mode", "shared"))
        allowed = set(policy.get("tenant_ids") or policy.get("allow_tenants") or [])
        denied = set(policy.get("deny_tenants") or [])
        if mode == "denied":
            return False
        if tenant_id is None:
            return mode != "private"
        if tenant_id in denied:
            return False
        if mode == "private":
            return tenant_id in allowed
        if allowed:
            return tenant_id in allowed
        return True

    def _agent_resources_satisfy(self, agent: Agent, machine: Machine, task: Task) -> bool:
        required = task.metadata.get("resources") or task.metadata.get("required_resources") or {}
        if isinstance(required, dict):
            available = dict(machine.resources)
            available.update(agent.resources)
            for key, needed in required.items():
                current = available.get(key)
                if isinstance(needed, (int, float)):
                    if current is None or float(current) < float(needed):
                        return False
                elif isinstance(needed, list):
                    if not set(needed).issubset(set(current or [])):
                        return False
                elif needed is not None and current != needed:
                    return False
        # Structured hardware constraints on the task (set by the workflow
        # runtime when spawning a role-bound node task). Falls through the
        # shared matcher so the role-required-hardware vocabulary stays in
        # one place.
        hw_required = task.metadata.get("hardware") if isinstance(task.metadata, dict) else None
        if isinstance(hw_required, dict) and hw_required:
            from mac.roles_service import machine_hardware_satisfies

            ok, _reasons = machine_hardware_satisfies(hw_required, machine.hardware)
            if not ok:
                return False
        return True

    def _expire_agent_active_leases(self, agent_id: str, timestamp: str, reason: str) -> None:
        liveness_loss = reason in {"heartbeat_offline", "agent_update_offline"}
        rows = self.store.query_all(
            """
            SELECT
                l.id AS lease_id,
                l.task_id AS task_id,
                t.state AS task_state,
                t.attempt_count AS attempt_count,
                t.max_attempts AS max_attempts
            FROM leases l
            JOIN tasks t ON t.lease_id = l.id
            WHERE l.agent_id = ?
              AND l.status = ?
              AND t.owner_agent_id = ?
            ORDER BY l.created_at, l.id
            """,
            (agent_id, LeaseStatus.ACTIVE.value, agent_id),
        )
        if not rows:
            return
        # Do not maintain a second, weaker expiry implementation here.  An
        # offline event may force an otherwise clock-live lease to EXPIRED and
        # refund its attempt, but durable finalizer ownership, persisted
        # decision, package repair receipt, WIP handling, task detach, and node
        # transition must all run through the same resumable path as the normal
        # sweeper.
        for row in rows:
            if liveness_loss:
                next_state = TaskState.OPEN.value
            elif row["attempt_count"] >= row["max_attempts"]:
                next_state = TaskState.FAILED.value
            else:
                next_state = TaskState.OPEN.value
            attempt_count_after = max(
                0,
                int(row["attempt_count"]) - (1 if liveness_loss else 0),
            )
            detail = {
                "lease_id": row["lease_id"],
                "agent_id": agent_id,
                "reason": reason,
                "failure_class": "environment" if liveness_loss else "work",
                "attempt_refunded": liveness_loss,
                "attempt_count_before": int(row["attempt_count"]),
                "attempt_count_after": attempt_count_after,
            }
            decision = {
                "schema": "mac.lease_expiry_decision.v1",
                "lease_id": row["lease_id"],
                "task_id": row["task_id"],
                "target_state": next_state,
                "reset_attempt_count": False,
                "attempt_count_after": attempt_count_after,
                "detail": detail,
            }
            lease_row = self.store.query_one(
                "SELECT * FROM leases WHERE id = ?",
                (row["lease_id"],),
            )
            if lease_row is None:
                continue
            try:
                self._expire_lease_row(
                    lease_row,
                    force_expire=True,
                    decision_override=decision,
                )
            except Exception as exc:  # noqa: BLE001 - isolate one stale assignment.
                try:
                    self.record_log(
                        "lease.recovery.failed",
                        layer="control_plane",
                        source="dispatcher",
                        level="error",
                        subject_type="lease",
                        subject_id=str(row["lease_id"]),
                        detail={
                            "lease_id": str(row["lease_id"]),
                            "reason": reason,
                            "error": str(exc),
                        },
                    )
                except Exception:
                    pass
        for row in rows:
            # Self-documenting: a lease expiry means the agent stopped heartbeating
            # mid-task (offline / crash / long synchronous op like a big clone).
            # Record the cause + remediation on the task (visible in `mac task
            # show`/`summary`) whether it was requeued (OPEN) or failed out. The
            # BLOCKED target arg only selects the matching note text.
            try:
                diag = _failure_diagnosis(TaskState.BLOCKED.value, {"reason": reason})
                if diag:
                    self.append_task_activity(row["task_id"], "diagnosis", "dispatcher", diag)
            except Exception:  # noqa: BLE001 - advisory only
                pass
